INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l41','needn''t have done','',NULL,'/ˈniːdnt həv duːn/','You needn''t have said that.','你本来用不着说那话。','You needn''t have waited for me.','你本来不必等我的。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l41','mustn''t do sth','',NULL,'/ˈmʌsnt duː/','We mustn''t buy things we don''t need.','我们不该买不需要的东西。','You mustn''t smoke here.','这儿不许抽烟。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l41','remind sb of sth','',NULL,'/rɪˈmaɪnd ... ʌv/','I needn''t remind you of that terrible tie.','我不必提醒你想起那条难看的领带。','This photo reminds me of my childhood.','这张照片让我想起童年。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l41','regret doing sth','',NULL,'/rɪˈɡret ˈduːɪŋ/','I regretted saying it almost at once.','我几乎立刻就后悔说了那话。','She regretted buying so many hats.','她后悔买了那么多帽子。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',5,'am2_l41_gp1','choice','{"stem":"\"I ___ a new hat, so I must buy one.\"(表''需要''的那个动词)","options":["have","needn''t","must","need"],"answer_index":3,"stem_cn":"我需要一顶新帽子,所以得买一顶。","explanation_cn":"need 作\"需要\"讲(普通动词)。✓ I need a new hat 我需要一顶新帽子。✗ needn''t:那是\"不必\";✗ must:是\"必须\";✗ have:此处不搭。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',5,'am2_l41_gp1','choice','{"stem":"\"I won''t buy that. I don''t ___ it.\"(不需要)","options":["needn''t","have","need","must"],"answer_index":2,"stem_cn":"我不会买那个,我不需要它。","explanation_cn":"don''t need 表\"不需要\"。✓ I don''t need it 我不需要它。✗ needn''t:与 don''t 重复;✗ must / have:意思不符。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',5,'am2_l41_gp2','choice','{"stem":"\"You ___ leave your car here. Can''t you see the ''No Parking'' sign?\"(禁止、不许)","options":["mustn''t","don''t","aren''t","needn''t"],"answer_index":0,"stem_cn":"你不许把车停这儿,没看见''禁止停车''的牌子吗?","explanation_cn":"禁止、不许用 mustn''t。✓ You mustn''t leave your car here 你不许把车停这儿。✗ needn''t:那是\"不必\",但这里是明令禁止;✗ don''t / aren''t:语气与\"禁令\"不符。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',5,'am2_l41_gp2','choice','{"stem":"\"You ___ drive so quickly; we have plenty of time.\"(没必要,可做可不做)","options":["mustn''t","don''t","aren''t","needn''t"],"answer_index":3,"stem_cn":"你不必开这么快,我们时间还多。","explanation_cn":"时间充裕、没必要,用 needn''t。✓ You needn''t drive so quickly 你不必开这么快。✗ mustn''t:那是\"不许\",意思太重;✗ don''t / aren''t:不搭。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',5,'am2_l41_gp2','choice','{"stem":"\"You ___ smoke in the theater. It is forbidden.\"(禁止、被明令不许)","options":["won''t","don''t","mustn''t","needn''t"],"answer_index":2,"stem_cn":"剧院里不许抽烟,这是禁止的。","explanation_cn":"It is forbidden 明确表示\"被禁止\",用 mustn''t。✓ You mustn''t smoke in the theater 剧院里不许抽烟。✗ needn''t:那是\"不必\",与\"forbidden\"矛盾;✗ don''t / won''t:语气不符。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',5,'am2_l41_gp2','choice','{"stem":"\"You ___ come with us if you don''t want to.\"(没必要)","options":["needn''t","mustn''t","can''t","don''t"],"answer_index":0,"stem_cn":"你要是不想来,不必和我们一起去。","explanation_cn":"\"要是不想就没必要\",用 needn''t。✓ You needn''t come with us 你不必和我们一起去。✗ mustn''t:那是\"不许\";✗ can''t:是\"不能\";✗ don''t:不搭。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',5,'am2_l41_gp3','choice','{"stem":"\"You needn''t wait for me. = You ___ wait for me.\"(同义替换:不必)","options":["have to","must not","don''t have to","haven''t"],"answer_index":2,"stem_cn":"你不必等我。","explanation_cn":"needn''t = don''t have to,都表\"不必\"。✓ You don''t have to wait for me 你不必等我。✗ must not:那是\"不许\";✗ have to:是\"必须\";✗ haven''t:不完整。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',5,'am2_l41_gp3','choice','{"stem":"\"You don''t have to come. = You ___ come.\"(同义替换:不必)","options":["have to","mustn''t","must","needn''t"],"answer_index":3,"stem_cn":"你不必来。","explanation_cn":"don''t have to = needn''t,都表\"不必\"。✓ You needn''t come 你不必来。✗ mustn''t:那是\"不许\";✗ must / have to:是\"必须\"。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',5,'am2_l41_gp4','choice','{"stem":"\"You ___ said that — now she''s upset.\"(本来用不着做,却做了)","options":["needn''t have","mustn''t","don''t have to","needn''t"],"answer_index":0,"stem_cn":"你本来用不着说那句话——现在她生气了。","explanation_cn":"\"本来用不着做,却已经做了\"用 needn''t have + 过去分词。✓ You needn''t have said that 你本来用不着说那话。✗ needn''t:那是\"现在不必\";✗ don''t have to:是\"现在不必\";✗ mustn''t:是\"不许\"。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',5,'am2_l41_gp4','choice','{"stem":"\"You needn''t ___ waited for me; I was fine on my own.\"(本来不必等,却等了)","options":["has","having","had","have"],"answer_index":3,"stem_cn":"你本来不必等我的,我自己没问题。","explanation_cn":"needn''t have + 过去分词表\"本来不必却做了\"。✓ You needn''t have waited 你本来不必等。✗ has / had / having:与 needn''t 搭配要用 have + 过去分词。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',5,'am2_l41_gp5','choice','{"stem":"\"I ___ leave now, or I''ll miss the train.\"(必须)","options":["needn''t","must","mustn''t","don''t"],"answer_index":1,"stem_cn":"我必须走了,不然会赶不上火车。","explanation_cn":"\"必须、一定要\"用 must。✓ I must leave now 我必须走了。✗ needn''t:是\"不必\";✗ mustn''t:是\"不许\";✗ don''t:不搭。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',5,'am2_l41_gp5','choice','{"stem":"\"It''s a rule here: you ___ wear a seatbelt.\"(规定、不得不)","options":["haven''t","don''t","needn''t","have to"],"answer_index":3,"stem_cn":"这里有规定:你必须系安全带。","explanation_cn":"规定、客观要求\"不得不\"用 have to。✓ you have to wear a seatbelt 你必须系安全带。✗ needn''t:是\"不必\";✗ haven''t / don''t:不搭。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',5,'am2_l41_gp6','choice','{"stem":"\"I remarked it, but I regretted ___ it almost at once.\"(对做过的事后悔,后接动名词)","options":["to say","say","saying","said"],"answer_index":2,"stem_cn":"我说了那话,但几乎立刻就后悔说了。","explanation_cn":"regret + 动名词,表示对做过的事后悔。✓ I regretted saying it 我后悔说了那话。✗ to say:regret to do 是\"遗憾地(要)去说\",时间点不同;✗ say / said:结构不对。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',5,'am2_l41_gp6','choice','{"stem":"\"She regretted ___ so many hats.\"(对做过的事后悔,后接动名词)","options":["buying","to buy","buy","bought"],"answer_index":0,"stem_cn":"她后悔买了那么多帽子。","explanation_cn":"regret + 动名词,对做过的事后悔。✓ She regretted buying so many hats 她后悔买了那么多帽子。✗ to buy:表\"遗憾地要去买\",不合;✗ buy / bought:结构不对。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',5,'am2_l41_gp7','choice','{"stem":"\"I needn''t remind you ___ that terrible tie.\"(提醒某人想起某事的固定搭配)","options":["for","in","at","of"],"answer_index":3,"stem_cn":"我不必提醒你想起那条难看的领带。","explanation_cn":"remind sb of sth 是\"提醒某人想起某事\"。✓ remind you of that tie 提醒你想起那条领带。✗ for / at / in:不与 remind 搭配这个意思。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',5,'am2_l41_gp7','choice','{"stem":"\"This photo reminds me ___ my childhood.\"(提醒某人想起某事的固定搭配)","options":["in","for","of","at"],"answer_index":2,"stem_cn":"这张照片让我想起童年。","explanation_cn":"remind sb of sth\"使某人想起某事\"。✓ reminds me of my childhood 让我想起童年。✗ for / at / in:不搭。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',5,'am2_l41_gp8','choice','{"stem":"\"Did you ___ how she was dressed?\"(注意到)","options":["remark","regret","remind","notice"],"answer_index":3,"stem_cn":"你注意到她的穿着了吗?","explanation_cn":"\"注意到\"用 notice。✓ Did you notice how she was dressed? 你注意到她的穿着了吗?✗ remark:是\"评论、说\";✗ remind:是\"提醒\";✗ regret:是\"后悔\"。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',5,'am2_l41_gp8','choice','{"stem":"\"''We mustn''t buy things we don''t need,'' I ___.\"(评论、说道)","options":["remarked","reminded","regretted","noticed"],"answer_index":0,"stem_cn":"''我们不该买不需要的东西,''我评论道。","explanation_cn":"\"评论、说道\"用 remark。✓ I remarked 我评论道。✗ reminded:是\"提醒\";✗ noticed:是\"注意到\";✗ regretted:是\"后悔\"。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',6,NULL,'choice','{"stem":"美语里\"商店\"常说:","options":["stall","store","market","shop"],"answer_index":1,"explanation_cn":"美语\"商店\"常说 store;英式说 shop。✓ a hat store 帽子店。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',6,NULL,'choice','{"stem":"美语里\"裤子\"常说:","options":["pants","trousers","slacks","shorts"],"answer_index":0,"explanation_cn":"美语\"裤子\"常说 pants;英式说 trousers。✓ a pair of pants 一条裤子。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',6,NULL,'choice','{"stem":"rude 的意思是:","options":["友好的","害羞的","诚实的","无礼的,粗鲁的"],"answer_index":3,"explanation_cn":"rude = 无礼的、粗鲁的。✓ You needn''t be so rude 你没必要这么无礼。\n顺带记:友好的 = friendly;害羞的 = shy;诚实的 = honest."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',6,NULL,'choice','{"stem":"mirror 的意思是:","options":["门","镜子","画框","窗户"],"answer_index":1,"explanation_cn":"mirror = 镜子。✓ looked at herself in the mirror 对着镜子看自己。\n顺带记:窗户 = window;画框 = frame;门 = door."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',6,NULL,'choice','{"stem":"remind 的意思是:","options":["评论","注意","忘记","提醒"],"answer_index":3,"explanation_cn":"remind = 提醒。✓ remind you of that tie 提醒你想起那条领带。\n顺带记:忘记 = forget;评论 = remark;注意 = notice."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',6,NULL,'choice','{"stem":"lighthouse 的意思是:","options":["灯塔","仓库","城堡","农舍"],"answer_index":0,"explanation_cn":"lighthouse = 灯塔。✓ a hat that looked like a lighthouse 一顶像灯塔的帽子。\n顺带记:仓库 = warehouse;城堡 = castle;农舍 = cottage."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',7,NULL,'cloze','{"stem":"第 1 空","context":"In the hat shop, the wife tried on hats for half an hour. ''We ___1___ buy things we don''t ___2___,'' the husband remarked. ''You ___3___ have said that,'' she answered. ''I ___4___ buy at least one hat.''","blank_no":1,"options":["mustn''t","needn''t","don''t","haven''t"],"answer_index":0,"explanation_cn":"\"不该买不需要的东西\",语气偏禁止/告诫,用 mustn''t。✓ We mustn''t buy things we don''t need。\n✗ needn''t:那是\"不必\";✗ don''t / haven''t:不搭。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',7,NULL,'cloze','{"stem":"第 2 空","context":"In the hat shop, the wife tried on hats for half an hour. ''We ___1___ buy things we don''t ___2___,'' the husband remarked. ''You ___3___ have said that,'' she answered. ''I ___4___ buy at least one hat.''","blank_no":2,"options":["need","needn''t","must","have"],"answer_index":0,"explanation_cn":"\"我们不需要的东西\",need 作\"需要\"讲。✓ things we don''t need 我们不需要的东西。\n✗ needn''t:与 don''t 重复;✗ must / have:意思不符。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',7,NULL,'cloze','{"stem":"第 3 空","context":"In the hat shop, the wife tried on hats for half an hour. ''We ___1___ buy things we don''t ___2___,'' the husband remarked. ''You ___3___ have said that,'' she answered. ''I ___4___ buy at least one hat.''","blank_no":3,"options":["needn''t","mustn''t","don''t","haven''t"],"answer_index":0,"explanation_cn":"\"本来用不着说,却说了\"用 needn''t have。✓ You needn''t have said that 你本来用不着说那话。\n✗ mustn''t:是\"不许\";✗ don''t / haven''t:不搭。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',7,NULL,'cloze','{"stem":"第 4 空","context":"In the hat shop, the wife tried on hats for half an hour. ''We ___1___ buy things we don''t ___2___,'' the husband remarked. ''You ___3___ have said that,'' she answered. ''I ___4___ buy at least one hat.''","blank_no":4,"options":["must","needn''t","mustn''t","don''t"],"answer_index":0,"explanation_cn":"\"至少得买一顶\",必须,用 must。✓ I must buy at least one hat 我至少得买一顶帽子。\n✗ needn''t:是\"不必\";✗ mustn''t:是\"不许\";✗ don''t:不搭。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',8,NULL,'choice','{"stem":"Where were the writer and his wife?","options":["In a hat shop","At a restaurant","In a theater","At home"],"answer_index":0,"explanation_cn":"课文说 We had been in the hat shop for half an hour,他们在帽店里。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',8,NULL,'choice','{"stem":"What did the writer say they shouldn''t do?","options":["Leave the shop","Talk to the salesgirl","Buy things they don''t need","Try on hats"],"answer_index":2,"explanation_cn":"课文说 We mustn''t buy things we don''t need,他说不该买不需要的东西。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',8,NULL,'choice','{"stem":"What did the wife''s hat look like in the end?","options":["A boat","A bird","A flower","A lighthouse"],"answer_index":3,"explanation_cn":"课文结尾说 a hat that looked like a lighthouse,那帽子像座灯塔。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',9,NULL,'choice','{"stem":"你想说\"这儿不许抽烟,是禁止的\"(禁止用 mustn''t):","options":["You mustn''t to smoke here; it''s forbidden.","You mustn''t smoke here; it''s forbidden.","You needn''t smoke here; it''s forbidden.","You don''t smoke here; it''s forbidden."],"answer_index":1,"explanation_cn":"禁止、被明令不许用 mustn''t。✓ You mustn''t smoke here; it''s forbidden. 场合:提醒对方某事是明令禁止的。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',9,NULL,'choice','{"stem":"你想说\"你不必等我,我没关系\"(不必用 needn''t):","options":["You don''t need wait for me; I''m fine.","You mustn''t wait for me; I''m fine.","You needn''t to wait for me; I''m fine.","You needn''t wait for me; I''m fine."],"answer_index":3,"explanation_cn":"\"没必要、可做可不做\"用 needn''t,后接动词原形。✓ You needn''t wait for me; I''m fine. 场合:告诉对方不用为你费事。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',9,NULL,'choice','{"stem":"你想说\"你本来用不着说那句话\"(本来不必却做了):","options":["You needn''t say that.","You mustn''t say that.","You needn''t have said that.","You didn''t need say that."],"answer_index":2,"explanation_cn":"\"本来用不着做,却已经做了\"用 needn''t have + 过去分词。✓ You needn''t have said that. 场合:埋怨对方说了不该说的话。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',10,NULL,'choice','{"stem":"rude 的意思是:","options":["勇敢的","无礼的,粗鲁的","友好的","聪明的"],"answer_index":1,"explanation_cn":"rude = 无礼的、粗鲁的。✓ so rude 这么无礼。\n顺带记:友好的 = friendly;勇敢的 = brave;聪明的 = clever."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',10,NULL,'choice','{"stem":"lighthouse 的意思是:","options":["城堡","农舍","仓库","灯塔"],"answer_index":3,"explanation_cn":"lighthouse = 灯塔。✓ like a lighthouse 像座灯塔。\n顺带记:城堡 = castle;仓库 = warehouse;农舍 = cottage."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',10,NULL,'choice','{"stem":"\"You ___ smoke here — it''s forbidden.\"(禁止,不许)","options":["don''t","won''t","mustn''t","needn''t"],"answer_index":2,"stem_cn":"这儿不许抽烟——是禁止的。","explanation_cn":"it''s forbidden 表示被禁止,用 mustn''t。✓ You mustn''t smoke here 这儿不许抽烟。\n✗ needn''t:是\"不必\";✗ don''t / won''t:语气不符。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',10,NULL,'choice','{"stem":"\"You ___ wait for me; I''m fine on my own.\"(不必,没必要)","options":["haven''t","mustn''t","aren''t","needn''t"],"answer_index":3,"stem_cn":"你不必等我,我自己没问题。","explanation_cn":"\"没必要、我自己行\"用 needn''t。✓ You needn''t wait for me 你不必等我。\n✗ mustn''t:是\"不许\";✗ aren''t / haven''t:不搭。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',10,NULL,'choice','{"stem":"\"You needn''t have said that.\" 这句话的意思是:","options":["你本来用不着说那句话(却说了)。","你必须说那句话。","你现在别说那句话。","你没说那句话。"],"answer_index":0,"explanation_cn":"You needn''t have said that. needn''t have done 表\"本来用不着做却做了\",意思是\"你本来用不着说那句话(却说了)\"。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',10,NULL,'choice','{"stem":"\"A man can never have too many ties.\" 这句话的意思是:","options":["男人只需要一条领带。","男人有多少领带也不嫌多。","男人不该有太多领带。","男人从不打领带。"],"answer_index":1,"explanation_cn":"A man can never have too many ties. can never have too many 表\"再多也不嫌多\",意思是\"男人有多少领带也不嫌多\"。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',10,NULL,'choice','{"stem":"Why did the writer say ''We mustn''t buy things we don''t need''?","options":["He thought his wife was spending too long buying a hat","He liked the modern chairs","He was hungry","He wanted to buy a hat himself"],"answer_index":0,"passage":"''Do you call that a hat?'' I said to my wife. ''You needn''t be so rude about it,'' my wife answered as she looked at herself in the mirror. I sat down on one of those modern chairs with holes in it and waited. We had been in the hat shop for half an hour and my wife was still in front of the mirror. ''We mustn''t buy things we don''t need,'' I remarked suddenly. I regretted saying it almost at once. ''You needn''t have said that,'' my wife answered. ''I needn''t remind you of that terrible tie you bought yesterday.'' ''I find it beautiful,'' I said. ''A man can never have too many ties.'' ''And a woman can''t have too many hats,'' she answered. Ten minutes later we walked out of the shop together. My wife was wearing a hat that looked like a lighthouse!","explanation_cn":"课文里妻子试帽半小时还在镜子前,丈夫等得不耐烦,才说不该买不需要的东西。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',10,NULL,'choice','{"stem":"How did the wife reply to his complaint?","options":["She put the hat back","She reminded him of the terrible tie he had bought","She left the shop alone","She agreed with him at once"],"answer_index":1,"passage":"''Do you call that a hat?'' I said to my wife. ''You needn''t be so rude about it,'' my wife answered as she looked at herself in the mirror. I sat down on one of those modern chairs with holes in it and waited. We had been in the hat shop for half an hour and my wife was still in front of the mirror. ''We mustn''t buy things we don''t need,'' I remarked suddenly. I regretted saying it almost at once. ''You needn''t have said that,'' my wife answered. ''I needn''t remind you of that terrible tie you bought yesterday.'' ''I find it beautiful,'' I said. ''A man can never have too many ties.'' ''And a woman can''t have too many hats,'' she answered. Ten minutes later we walked out of the shop together. My wife was wearing a hat that looked like a lighthouse!","explanation_cn":"妻子回敬说 I needn''t remind you of that terrible tie you bought yesterday,拿他买的难看领带反驳。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',10,NULL,'choice','{"stem":"How long had they been in the hat shop?","options":["Five minutes","All morning","Two hours","Half an hour"],"answer_index":3,"audio":"''Do you call that a hat?'' I said to my wife. ''You needn''t be so rude about it,'' my wife answered as she looked at herself in the mirror. I sat down on one of those modern chairs with holes in it and waited. We had been in the hat shop for half an hour and my wife was still in front of the mirror. ''We mustn''t buy things we don''t need,'' I remarked suddenly. I regretted saying it almost at once. ''You needn''t have said that,'' my wife answered. ''I needn''t remind you of that terrible tie you bought yesterday.'' ''I find it beautiful,'' I said. ''A man can never have too many ties.'' ''And a woman can''t have too many hats,'' she answered. Ten minutes later we walked out of the shop together. My wife was wearing a hat that looked like a lighthouse!","explanation_cn":"课文说 We had been in the hat shop for half an hour,他们在帽店呆了半小时。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l41',10,NULL,'choice','{"stem":"In the end, did the wife buy a hat?","options":["Yes — one that looked like a lighthouse","No — the shop was closed","Yes — a plain black one","No — they left with nothing"],"answer_index":0,"audio":"''Do you call that a hat?'' I said to my wife. ''You needn''t be so rude about it,'' my wife answered as she looked at herself in the mirror. I sat down on one of those modern chairs with holes in it and waited. We had been in the hat shop for half an hour and my wife was still in front of the mirror. ''We mustn''t buy things we don''t need,'' I remarked suddenly. I regretted saying it almost at once. ''You needn''t have said that,'' my wife answered. ''I needn''t remind you of that terrible tie you bought yesterday.'' ''I find it beautiful,'' I said. ''A man can never have too many ties.'' ''And a woman can''t have too many hats,'' she answered. Ten minutes later we walked out of the shop together. My wife was wearing a hat that looked like a lighthouse!","explanation_cn":"课文结尾说妻子戴着一顶像灯塔的帽子走出商店,说明她买了。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l42',2,6,42,'Not very musical','并非很懂音乐','have 的用法(KS18)主考——have / have got 表''拥有''(own/possess 的替换)、have + 名词代替普通动词(have a look / a good time / a drink / a talk);pick up(拿起/学会/接人)、pick out(挑选)、tell the difference between(辨别)、as soon as(一…就…)(辅考·课文/难点①类)。美语差:散步/洗澡/休息/看一看 美语多用 take a walk / bath / rest / look(见关6对照)','在旧德里的集市里走了很长一段路后,我们在一个广场上停下来休息。过了一会儿,注意到广场另一边有个带着两个大筐的耍蛇人,便走过去看。他一见我们,就拿起一根缠满硬币的长管,掀开一个筐。他吹起一支曲子,我们才第一次看到那条蛇。蛇从筐里探出身子,随着管子的摆动而扭动。当耍蛇人突然吹起爵士乐和现代流行乐时,我们非常惊奇——那蛇却还是慢慢地“舞动”着。显然,它分辨不出印度音乐和爵士乐!','{"q":"Listen and answer — What happened when the snake charmer began to play jazz?","options":["The snake kept ''dancing'' slowly, unable to tell it from Indian music","The snake danced much faster","The snake stopped and hid","The snake bit the charmer"],"answer_index":0}'::jsonb,'{"title":"have 的用法:拥有 & have + 名词 = 做某事","intro":"have / have got 可表''拥有''(替换 own / possess);还能 have + 名词来代替一个普通动词:have a look = 看一看,have a good time = 玩得开心,have a drink = 喝一杯。全用本课句子举例。","table":{"headers":["普通说法","have 说法"],"rows":[["He owns a new house.","He has (got) a new house.(拥有)"],["Look at this.","Have a look at this.(看一看)"],["I enjoyed myself at the party.","I had a good time at the party.(玩得开心)"],["He wanted to drink a glass of water.","He wanted to have a drink of water.(喝一杯)"],["We will talk about it tomorrow.","We will have a talk about it tomorrow.(谈一谈)"]]},"specialRules":[{"rule":"have got = have,都表''拥有'',口语里 have got 更常见:He has got a new car.","mark":"have got = 拥有"},{"rule":"美语差:散步/洗澡/休息/看一看,美语多用 take(take a walk / take a bath / take a rest / take a look);英式多用 have。","mark":"美语常用 take a walk/bath"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l42',1,NULL,'As we had had a long walk through one of the markets of Old Delhi, we stopped at a square to have a rest.','在旧德里的一个集市里走了很长一段路后,我们在一个广场上停下来休息。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l42',2,NULL,'After a time, we noticed a snake charmer with two large baskets at the other side of the square, so we went to have a look at him.','过了一会儿,我们注意到广场另一边有个带着两个大筐的耍蛇人,便走过去看。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l42',3,NULL,'As soon as he saw us, he picked up a long pipe which was covered with coins and opened one of the baskets.','他一看见我们,就拿起一根缠满硬币的长管,掀开一个筐。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l42',4,NULL,'When he began to play a tune, we had our first glimpse of the snake.','当他吹起一支曲子时,我们才第一次看到那条蛇。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l42',5,NULL,'It rose out of the basket and began to follow the movements of the pipe.','蛇从筐里探出身子,随着管子的摆动而扭动。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l42',6,NULL,'We were very much surprised when the snake charmer suddenly began to play jazz and modern pop songs.','当耍蛇人突然吹起爵士乐和现代流行乐时,我们感到非常惊奇。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l42',7,NULL,'The snake, however, continued to ''dance'' slowly.','然而那蛇却还是慢慢地“舞动”着。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l42',8,NULL,'It obviously could not tell the difference between Indian music and jazz!','显然,它分辨不出印度音乐和爵士乐!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
