INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l43','be able to','',NULL,'/bi ˈeɪbl tuː/','The plane was able to rise and clear the mountains.','飞机得以升高,越过了山头。','He will be able to see you tomorrow.','他明天能见你。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l43','run into (trouble)','',NULL,'/rʌn ˈɪntə/','They soon ran into serious trouble.','他们很快陷入了困境。','We ran into trouble on the way.','我们途中遇到了麻烦。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l43','order sb to do sth','',NULL,'/ˈɔːrdər ... tuː duː/','Byrd ordered his men to throw out the food sacks.','伯德命令部下把食物袋扔出去。','The captain ordered them to stop.','船长命令他们停下。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l43','get over','',NULL,'/ɡet ˈoʊvər/','The plane could only get over the mountains if it rose higher.','飞机只有升得更高才能越过山头。','How can we get over this difficulty?','我们怎样克服这个困难?') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',5,'am2_l43_gp1','choice','{"stem":"\"He will come if he is ___ to.\"(现在''能够'')","options":["possible","able","can","could"],"answer_index":1,"stem_cn":"他要是能来就会来。","explanation_cn":"be able to 表''能够'',结构 be + able + to。✓ if he is able to 如果他能。✗ can:不与 is…to 搭配;✗ could:同;✗ possible:是\"可能的\",不指人有能力。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',5,'am2_l43_gp1','choice','{"stem":"\"Are you ___ to help me now?\"(现在''能够'')","options":["able","possible","could","can"],"answer_index":0,"stem_cn":"你现在能帮我吗?","explanation_cn":"be able to 表''能够''。✓ Are you able to help me? 你能帮我吗?✗ can:不与 are…to 搭配;✗ could:同;✗ possible:不指人有能力。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',5,'am2_l43_gp2','choice','{"stem":"\"After I finish school next year, I ___ get a job.\"(将来才''能'',can 没有将来式)","options":["can","will be able to","could","am able to"],"answer_index":1,"stem_cn":"明年毕业后,我就能找份工作了。","explanation_cn":"can 没有将来式,说将来的''能''用 will be able to。✓ I will be able to get a job 我就能找到工作。✗ can:不表将来的''能'';✗ could:过去;✗ am able to:是现在。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',5,'am2_l43_gp2','choice','{"stem":"\"One day humans ___ live on Mars.\"(将来才''能'')","options":["are able to","could","can","will be able to"],"answer_index":3,"stem_cn":"总有一天人类能在火星上生活。","explanation_cn":"将来的''能''用 will be able to。✓ humans will be able to live on Mars 人类将能在火星生活。✗ can:不表将来;✗ could:过去;✗ are able to:现在。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',5,'am2_l43_gp2','choice','{"stem":"\"He said he ___ see me next week.\"(转述:将来''能'')","options":["is able to","can","would be able to","could"],"answer_index":2,"stem_cn":"他说他下周能见我。","explanation_cn":"转述里将来的''能''用 would be able to。✓ he would be able to see me 他将能见我。✗ can / could:不合转述里的将来;✗ is able to:现在。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',5,'am2_l43_gp3','choice','{"stem":"\"When I was young, I ___ run very fast.\"(过去''能够'')","options":["was able to","is able to","will be able to","am able to"],"answer_index":0,"stem_cn":"我小时候能跑得很快。","explanation_cn":"过去的''能''用 was able to。✓ I was able to run fast 我能跑得快。✗ am able to:现在;✗ will be able to:将来;✗ is able to:现在。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',5,'am2_l43_gp3','choice','{"stem":"\"At first they ___ take many photographs.\"(过去''能够'')","options":["is able to","will be able to","were able to","are able to"],"answer_index":2,"stem_cn":"起初他们能拍很多照片。","explanation_cn":"过去的''能''(复数主语)用 were able to。✓ they were able to take photographs 他们能拍照。✗ are able to:现在;✗ will be able to:将来;✗ is able to:单数现在。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',5,'am2_l43_gp4','choice','{"stem":"\"The plane ___ rise and cleared the mountains.\"(某一次''成功做到了'',强调结果)","options":["was able to","could","can","will"],"answer_index":0,"stem_cn":"飞机得以升高,越过了山头。","explanation_cn":"表某一次''终于成功做成'',只能用 was able to,不能用 could。✓ The plane was able to rise 飞机成功升高了。✗ could:表成功做成时不用;✗ can:现在;✗ will:将来。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',5,'am2_l43_gp4','choice','{"stem":"\"Byrd ___ reach the South Pole in the end.\"(某一次''成功做到了'',强调结果)","options":["is able to","could","was able to","can"],"answer_index":2,"stem_cn":"伯德最终成功飞抵南极。","explanation_cn":"某一次成功做成用 was able to。✓ Byrd was able to reach the Pole 伯德成功到达南极。✗ could:成功做成时不用;✗ can:现在;✗ is able to:现在。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',5,'am2_l43_gp4','choice','{"stem":"\"After hours of climbing, we ___ get to the top.\"(某一次''成功做到了'',强调结果)","options":["could","can","will","were able to"],"answer_index":3,"stem_cn":"爬了几个小时后,我们终于登顶了。","explanation_cn":"某一次成功做成用 were able to。✓ we were able to get to the top 我们成功登顶。✗ could:成功做成时不用;✗ can:现在;✗ will:将来。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',5,'am2_l43_gp4','choice','{"stem":"\"The firemen ___ put out the fire quickly.\"(某一次''成功做到了'',强调结果)","options":["were able to","can","are able to","could"],"answer_index":0,"stem_cn":"消防员迅速把火扑灭了。","explanation_cn":"某一次成功做成用 were able to。✓ the firemen were able to put out the fire 消防员成功灭火。✗ could:成功做成时不用;✗ can:现在;✗ are able to:现在。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',5,'am2_l43_gp5','choice','{"stem":"\"They soon ___ serious trouble.\"(遇到麻烦)","options":["ran over","ran after","ran out","ran into"],"answer_index":3,"stem_cn":"他们很快陷入了严重的困境。","explanation_cn":"run into (trouble) 表\"遇到、陷入(麻烦)\"。✓ ran into serious trouble 陷入严重困境。✗ ran out:用光;✗ ran after:追赶;✗ ran over:碾过。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',5,'am2_l43_gp5','choice','{"stem":"\"We ___ trouble when the car broke down.\"(遇到麻烦)","options":["ran out","ran away","ran into","ran after"],"answer_index":2,"stem_cn":"车抛锚时我们遇到了麻烦。","explanation_cn":"run into trouble 表\"遇到麻烦\"。✓ ran into trouble 遇到麻烦。✗ ran out:用光;✗ ran away:逃跑;✗ ran after:追赶。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',5,'am2_l43_gp6','choice','{"stem":"\"Byrd ___ his men to throw out two food sacks.\"(命令某人做某事)","options":["said","spoke","suggested","ordered"],"answer_index":3,"stem_cn":"伯德命令部下扔出两个食物袋。","explanation_cn":"order sb to do 表\"命令某人做某事\"。✓ ordered his men to throw out 命令部下扔出。✗ said:不接 sb to do;✗ spoke:不接宾语;✗ suggested:不接 sb to do。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',5,'am2_l43_gp6','choice','{"stem":"\"The captain ___ the sailors to lower the boat.\"(命令某人做某事)","options":["demanded","ordered","spoke","said"],"answer_index":1,"stem_cn":"船长命令水手放下小艇。","explanation_cn":"order sb to do\"命令某人做某事\"。✓ ordered the sailors to lower the boat 命令水手放艇。✗ said:不接 sb to do;✗ spoke:不接宾语;✗ demanded:不接 sb to do。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',5,'am2_l43_gp7','choice','{"stem":"\"They took ___ photographs of the mountains.\"(大量,后接可数名词复数)","options":["a little","a great deal of","a great many","much"],"answer_index":2,"stem_cn":"他们拍了大量群山的照片。","explanation_cn":"a great many 后接可数名词复数,表\"大量\"。✓ a great many photographs 大量照片。✗ a great deal of / much:接不可数;✗ a little:接不可数且意思相反。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',5,'am2_l43_gp8','choice','{"stem":"\"The plane could only ___ the mountains if it rose higher.\"(越过)","options":["get on","get over","get off","get up"],"answer_index":1,"stem_cn":"飞机只有升得更高才能越过山头。","explanation_cn":"get over 表\"越过、翻过\"。✓ get over the mountains 越过山头。✗ get on:上车/进展;✗ get off:下车;✗ get up:起床。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',5,'am2_l43_gp8','choice','{"stem":"\"It cleared the mountains ___ 400 feet.\"(表''相差'')","options":["by","in","of","with"],"answer_index":0,"stem_cn":"飞机在离山头400英尺处飞越过去。","explanation_cn":"by 在此表\"相差(多少)\"。✓ cleared the mountains by 400 feet 以相差400英尺越过。✗ with / of / in:不表\"相差\"。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',6,NULL,'choice','{"stem":"美语里\"飞机\"常说:","options":["aircraft","flyer","aeroplane","airplane"],"answer_index":3,"explanation_cn":"美语\"飞机\"常说 airplane;英式说 aeroplane。✓ a big airplane 一架大飞机。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',6,NULL,'choice','{"stem":"美语里\"手电筒\"常说:","options":["torch","light stick","flashlight","lamp"],"answer_index":2,"explanation_cn":"美语\"手电筒\"常说 flashlight;英式说 torch。✓ turn on the flashlight 打开手电筒。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',6,NULL,'choice','{"stem":"explorer 的意思是:","options":["司机","科学家","乘客","探险家"],"answer_index":3,"explanation_cn":"explorer = 探险家。✓ the American explorer 那位美国探险家。\n顺带记:乘客 = passenger;司机 = driver;科学家 = scientist."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',6,NULL,'choice','{"stem":"serious 的意思是:","options":["严重的;严肃的","简单的","有趣的","短暂的"],"answer_index":0,"explanation_cn":"serious = 严重的;严肃的。✓ serious trouble 严重的困境。\n顺带记:有趣的 = interesting;简单的 = simple;短暂的 = brief."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',6,NULL,'choice','{"stem":"endless 的意思是:","options":["危险的","狭窄的","有限的","无尽的"],"answer_index":3,"explanation_cn":"endless = 无尽的。✓ the endless white plains 茫茫无际的白色原野。\n顺带记:有限的 = limited;狭窄的 = narrow;危险的 = dangerous."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',6,NULL,'choice','{"stem":"crash 的意思是:","options":["坠毁,撞毁","转弯","起飞","降落"],"answer_index":0,"explanation_cn":"crash = 坠毁、撞毁。✓ the plane would crash 飞机会坠毁。\n顺带记:起飞 = take off;降落 = land;转弯 = turn."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',7,NULL,'cloze','{"stem":"第 1 空","context":"In 1929, Byrd ___1___ fly over the South Pole. At first his men ___2___ take many photographs, but they soon ran into trouble. The plane ___3___ rise only after they threw out two food sacks. In the end, the plane ___4___ clear the mountains and reach the Pole.","blank_no":1,"options":["was able to","can","could","is able to"],"answer_index":0,"explanation_cn":"表某一次''成功飞越了'',用 was able to。✓ Byrd was able to fly over the South Pole 伯德成功飞越南极。\n✗ can:现在;✗ could:成功做成时不用;✗ is able to:现在。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',7,NULL,'cloze','{"stem":"第 2 空","context":"In 1929, Byrd ___1___ fly over the South Pole. At first his men ___2___ take many photographs, but they soon ran into trouble. The plane ___3___ rise only after they threw out two food sacks. In the end, the plane ___4___ clear the mountains and reach the Pole.","blank_no":2,"options":["were able to","are able to","can","will be able to"],"answer_index":0,"explanation_cn":"起初能拍照(复数主语),过去的''能''用 were able to。✓ his men were able to take photographs。\n✗ are able to:现在;✗ can:现在;✗ will be able to:将来。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',7,NULL,'cloze','{"stem":"第 3 空","context":"In 1929, Byrd ___1___ fly over the South Pole. At first his men ___2___ take many photographs, but they soon ran into trouble. The plane ___3___ rise only after they threw out two food sacks. In the end, the plane ___4___ clear the mountains and reach the Pole.","blank_no":3,"options":["was able to","can","could","is able to"],"answer_index":0,"explanation_cn":"扔掉食物袋后飞机''终于成功升高'',用 was able to。✓ The plane was able to rise。\n✗ can:现在;✗ could:成功做成时不用;✗ is able to:现在。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',7,NULL,'cloze','{"stem":"第 4 空","context":"In 1929, Byrd ___1___ fly over the South Pole. At first his men ___2___ take many photographs, but they soon ran into trouble. The plane ___3___ rise only after they threw out two food sacks. In the end, the plane ___4___ clear the mountains and reach the Pole.","blank_no":4,"options":["was able to","can","could","is able to"],"answer_index":0,"explanation_cn":"最终''成功越过并到达'',用 was able to。✓ the plane was able to clear the mountains。\n✗ can:现在;✗ could:成功做成时不用;✗ is able to:现在。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',8,NULL,'choice','{"stem":"Who was the first man to fly over the South Pole?","options":["The American explorer R.E. Byrd","An Italian climber","A French sailor","A British pilot"],"answer_index":0,"explanation_cn":"课文说 the American explorer, R.E. Byrd, successfully flew over the South Pole for the first time。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',8,NULL,'choice','{"stem":"Why did Byrd order his men to throw out the food sacks?","options":["To make room for photographs","So the plane could rise high enough to clear the mountains","Because they were too heavy to carry home","Because the food was bad"],"answer_index":1,"explanation_cn":"课文说他命令扔掉食物袋,飞机才得以升高越过山头。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',8,NULL,'choice','{"stem":"How did the plane finally get over the mountains?","options":["It landed and waited","It crashed into them","It flew around them","It rose and cleared them by 400 feet"],"answer_index":3,"explanation_cn":"课文说 The plane was then able to rise and it cleared the mountains by 400 feet。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',9,NULL,'choice','{"stem":"你想说\"飞机终于成功升高越过了山头\"(表''成功做到''用 was able to,不用 could):","options":["The plane could rise and clear the mountains.","The plane is able to rise and clear the mountains.","The plane able to rise and clear the mountains.","The plane was able to rise and clear the mountains."],"answer_index":3,"explanation_cn":"表某一次''成功做成''用 was able to,不用 could。✓ The plane was able to rise and clear the mountains. 场合:强调经过努力终于做成了一件事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',9,NULL,'choice','{"stem":"你想说\"我明天就能见你\"(将来的''能''用 will be able to):","options":["I''ll be able to see you tomorrow.","I am able see you tomorrow.","I will can see you tomorrow.","I be able to see you tomorrow."],"answer_index":0,"explanation_cn":"将来的''能''用 will be able to(can 没有将来式)。✓ I''ll be able to see you tomorrow. 场合:说自己将来能做某事。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',9,NULL,'choice','{"stem":"你想说\"他们很快遇到了严重的麻烦\"(遇到麻烦用 run into):","options":["They soon ran out serious trouble.","They soon ran after serious trouble.","They soon ran into serious trouble.","They soon ran serious trouble into."],"answer_index":2,"explanation_cn":"\"遇到、陷入(麻烦)\"用 run into。✓ They soon ran into serious trouble. 场合:说很快遇到了麻烦。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',10,NULL,'choice','{"stem":"explorer 的意思是:","options":["医生","乘客","士兵","探险家"],"answer_index":3,"explanation_cn":"explorer = 探险家。✓ the explorer 那位探险家。\n顺带记:乘客 = passenger;医生 = doctor;士兵 = soldier."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',10,NULL,'choice','{"stem":"endless 的意思是:","options":["狭窄的","无尽的","危险的","短暂的"],"answer_index":1,"explanation_cn":"endless = 无尽的。✓ endless plains 无尽的原野。\n顺带记:短暂的 = brief;狭窄的 = narrow;危险的 = dangerous."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',10,NULL,'choice','{"stem":"\"The plane ___ rise and cleared the mountains.\"(表''成功做到了'',不用 could)","options":["could","can","was able to","will"],"answer_index":2,"stem_cn":"飞机得以升高,越过了山头。","explanation_cn":"表某一次''成功做到了'',用 was able to,不用 could。✓ The plane was able to rise 飞机成功升高。\n✗ could:成功做成时不用;✗ can:现在;✗ will:将来。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',10,NULL,'choice','{"stem":"\"They soon ___ serious trouble.\"(遇到麻烦)","options":["ran out","ran after","ran over","ran into"],"answer_index":3,"stem_cn":"他们很快陷入了严重的困境。","explanation_cn":"run into (trouble) 表\"遇到、陷入麻烦\"。✓ ran into serious trouble 陷入严重困境。\n✗ ran out:用光;✗ ran after:追赶;✗ ran over:碾过。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',10,NULL,'choice','{"stem":"\"It cleared the mountains by 400 feet.\" 这句话的意思是:","options":["飞机在离山头400英尺的高度飞越了过去。","飞机在山头下方400英尺。","飞机撞上了山头。","飞机绕过了山头。"],"answer_index":0,"explanation_cn":"It cleared the mountains by 400 feet. clear = 越过,by 表\"相差\",意思是\"飞机在离山头400英尺的高度飞越了过去\"。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',10,NULL,'choice','{"stem":"\"Byrd ordered his men to throw out two heavy food sacks.\" 这句话的意思是:","options":["伯德自己扔掉了食物袋。","伯德请求部下多带些食物。","伯德命令部下把两个沉重的食物袋扔出去。","伯德把食物分给部下。"],"answer_index":2,"explanation_cn":"Byrd ordered his men to throw out two heavy food sacks. order sb to do = 命令某人做某事,意思是\"伯德命令部下把两个沉重的食物袋扔出去\"。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',10,NULL,'choice','{"stem":"Why did the plane nearly crash?","options":["The pilot fell asleep","It ran out of fuel","A storm hit it","It could not get over the mountains unless it rose to 10,000 feet"],"answer_index":3,"passage":"In 1929, three years after his flight over the North Pole, the American explorer, R.E. Byrd, successfully flew over the South Pole for the first time. Though, at first, Byrd and his men were able to take a great many photographs of the mountains that lay below, they soon ran into serious trouble. At one point, it seemed certain that their plane would crash. It could only get over the mountains if it rose to 10,000 feet. Byrd at once ordered his men to throw out two heavy food sacks. The plane was then able to rise and it cleared the mountains by 400 feet. Byrd now knew that he would be able to reach the South Pole which was 300 miles away, for there were no more mountains in sight. The aircraft was able to fly over the endless white plains without difficulty.","explanation_cn":"课文说飞机只有升到一万英尺才能越过山头,否则似乎肯定要坠毁。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',10,NULL,'choice','{"stem":"What did Byrd know once the plane cleared the mountains?","options":["That more mountains lay ahead","That he would be able to reach the South Pole, 300 miles away","That the plane would crash","That they had to turn back"],"answer_index":1,"passage":"In 1929, three years after his flight over the North Pole, the American explorer, R.E. Byrd, successfully flew over the South Pole for the first time. Though, at first, Byrd and his men were able to take a great many photographs of the mountains that lay below, they soon ran into serious trouble. At one point, it seemed certain that their plane would crash. It could only get over the mountains if it rose to 10,000 feet. Byrd at once ordered his men to throw out two heavy food sacks. The plane was then able to rise and it cleared the mountains by 400 feet. Byrd now knew that he would be able to reach the South Pole which was 300 miles away, for there were no more mountains in sight. The aircraft was able to fly over the endless white plains without difficulty.","explanation_cn":"课文说越过山头后,伯德知道他能飞抵300英里外的南极了,因为前面再没有山。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',10,NULL,'choice','{"stem":"How many years after his North Pole flight did Byrd fly over the South Pole?","options":["Three years","Twenty years","One year","Ten years"],"answer_index":0,"audio":"In 1929, three years after his flight over the North Pole, the American explorer, R.E. Byrd, successfully flew over the South Pole for the first time. Though, at first, Byrd and his men were able to take a great many photographs of the mountains that lay below, they soon ran into serious trouble. At one point, it seemed certain that their plane would crash. It could only get over the mountains if it rose to 10,000 feet. Byrd at once ordered his men to throw out two heavy food sacks. The plane was then able to rise and it cleared the mountains by 400 feet. Byrd now knew that he would be able to reach the South Pole which was 300 miles away, for there were no more mountains in sight. The aircraft was able to fly over the endless white plains without difficulty.","explanation_cn":"课文说 In 1929, three years after his flight over the North Pole,飞越北极3年之后。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l43',10,NULL,'choice','{"stem":"What lay beyond the mountains?","options":["The ocean","Another range of mountains","A large city","Endless white plains with no more mountains"],"answer_index":3,"audio":"In 1929, three years after his flight over the North Pole, the American explorer, R.E. Byrd, successfully flew over the South Pole for the first time. Though, at first, Byrd and his men were able to take a great many photographs of the mountains that lay below, they soon ran into serious trouble. At one point, it seemed certain that their plane would crash. It could only get over the mountains if it rose to 10,000 feet. Byrd at once ordered his men to throw out two heavy food sacks. The plane was then able to rise and it cleared the mountains by 400 feet. Byrd now knew that he would be able to reach the South Pole which was 300 miles away, for there were no more mountains in sight. The aircraft was able to fly over the endless white plains without difficulty.","explanation_cn":"课文说前面再没有山了,飞机飞过茫茫无际的白色原野。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l44',2,6,44,'Through the forest','穿过森林','动名词 -ing 的用法(KS20)主考——动名词作主语(Eating is a pleasure)、介词后用动名词(keen on cycling / without saying / for not letting)、动词后接动名词(start/keep/enjoy/mind + doing)、动名词的否定(not + doing);so…that / such…that、need + doing(表''需要被…'',被动含义)、run after / catch up with、out of breath(辅考·课文①类)','安·斯特林夫人和孩子们正在森林边野餐时,两个男人冲到她跟前,企图抢走她的手提包。争抢中带子扯断了,包落入两人手里,他们拔腿跑进树林。斯特林夫人非常气愤,不顾风险追了上去。她很快就上气不接下气了,但仍继续追赶。当她追上他们时,发现两人已坐下来,正翻看包里的东西,于是她直冲过去。两个男人吓了一大跳,扔下提包就逃跑了。“这提包带子需要修理,”斯特林夫人事后说道,“不过他们什么也没偷走。”','{"q":"Listen and answer — How did Mrs. Sterling get her bag back?","options":["She chased the thieves and ran straight at them until they dropped it","She called the police","She paid them money","Her children caught them"],"answer_index":0}'::jsonb,'{"title":"动名词 -ing:动词当名词用","intro":"动词加 -ing 变成动名词,可以像名词一样用:作句子开头(Eating is a pleasure)、放在介词后面(keen on cycling / without saying)、放在某些动词后面(start / keep / enjoy / mind + doing);否定就在前面加 not(not letting)。全用本课和 Key structures 的句子举例。","table":{"headers":["用法","例子"],"rows":[["作句子开头","Eating is always a pleasure.(吃是一种享受)"],["介词后","I am keen on cycling.(热衷骑车)"],["介词后","He sat there without saying anything.(一言不发)"],["动词后","Both men started running.(开始奔跑)"],["否定 not + doing","I apologize for not letting you know.(没让你知道)"]]},"specialRules":[{"rule":"enjoy / keep / mind / finish 等动词后面只能接动名词(-ing),不能接 to do:enjoy running(不是 enjoy to run)。","mark":"enjoy/keep/mind + doing"},{"rule":"need + doing 表示''需要被…''(被动含义):The strap needs mending = 背带需要(被)修理。","mark":"need + doing = 需要被…"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l44',1,NULL,'Mrs. Anne Sterling did not think of the risk she was taking when she ran through a forest after two men.','安·斯特林夫人穿过森林追赶两个男人时,并没有考虑到自己所冒的风险。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l44',2,NULL,'They had rushed up to her while she was having a picnic at the edge of a forest with her children and tried to steal her handbag.','刚才她和孩子们正在森林边野餐时,这两个人冲到她跟前,企图抢走她的手提包。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l44',3,NULL,'In the struggle, the strap broke and, with the bag in their possession, both men started running through the trees.','争抢中带子扯断了,包落入两人手里,他们拔腿跑进树林。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l44',4,NULL,'Mrs. Sterling got so angry that she ran after them.','斯特林夫人非常气愤,追了上去。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l44',5,NULL,'She was soon out of breath, but she continued to run.','她很快就上气不接下气了,但仍继续追赶。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l44',6,NULL,'When she caught up with them, she saw that they had sat down and were going through the contents of the bag, so she ran straight at them.','当她追上他们时,发现两人已坐下正翻看包里的东西,于是直冲过去。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l44',7,NULL,'The men got such a fright that they dropped the bag and ran away.','两个男人吓了一大跳,扔下提包就逃跑了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l44',8,NULL,'''The strap needs mending,'' said Mrs. Sterling later, ''but they did not steal anything.''','“这提包带子需要修理,”斯特林夫人事后说道,“不过他们什么也没偷走。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
