INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l45','must have been + 过去分词','',NULL,'/mʌst həv bɪn/','The wallet must have been found by a villager.','钱包一定是被村民捡到了。','My bag is gone; it must have been stolen.','我的包不见了,一定是被偷了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l45','had been + 过去分词','',NULL,'/həd bɪn/','A large sum of money had been lost.','一大笔钱丢失了。','The parcel had been sent to the wrong address.','包裹被寄错了地址。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l45','while + doing','',NULL,'/waɪl ˈduːɪŋ/','He lost his wallet while taking his savings to the post office.','他在送存款去邮局时丢了钱包。','Be careful while crossing the road.','过马路时要小心。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l45','in time(最后,终于)','',NULL,'/ɪn taɪm/','In time, all his money was paid back.','最后,他所有的钱都还回来了。','In time, she learned to forgive him.','最终,她学会了原谅他。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',5,'am2_l45_gp1','choice','{"stem":"\"This bridge ___ in 1942.\"(一般过去被动:被建造)","options":["is built","builds","was built","built"],"answer_index":2,"stem_cn":"这座桥建于1942年。","explanation_cn":"一般过去的被动:主语\"被…\"用 was/were + 过去分词。✓ The bridge was built 桥被建造。✗ built:那是主动;✗ builds:一般现在主动;✗ is built:现在被动,与 1942 不符。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',5,'am2_l45_gp1','choice','{"stem":"\"The thief ___ by the police.\"(一般过去被动:被逮捕)","options":["arrested","was arrested","arrests","is arresting"],"answer_index":1,"stem_cn":"小偷被警察抓住了。","explanation_cn":"一般过去被动 was + 过去分词。✓ The thief was arrested 小偷被逮捕。✗ arrested:主动;✗ arrests:现在主动;✗ is arresting:现在进行主动。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',5,'am2_l45_gp2','choice','{"stem":"\"Sam found out that the parcel ___ to the wrong address.\"(过去完成被动:被寄错)","options":["had sent","sent","had been sent","was sending"],"answer_index":2,"stem_cn":"萨姆发现包裹被寄错了地址。","explanation_cn":"过去完成的被动:had been + 过去分词。✓ the parcel had been sent 包裹已被寄出。✗ had sent:那是主动;✗ sent:一般过去主动;✗ was sending:过去进行主动。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',5,'am2_l45_gp2','choice','{"stem":"\"He told me the thief ___ by the police.\"(过去完成被动:已被逮捕)","options":["had arrested","had been arrested","was arresting","arrested"],"answer_index":1,"stem_cn":"他告诉我小偷已被警察抓住。","explanation_cn":"过去完成被动 had been + 过去分词。✓ the thief had been arrested 小偷已被逮捕。✗ had arrested:主动;✗ arrested:一般过去主动;✗ was arresting:过去进行主动。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',5,'am2_l45_gp2','choice','{"stem":"\"The village learnt that a large sum of money ___.\"(过去完成被动:已丢失)","options":["had been lost","had lost","lost","was losing"],"answer_index":0,"stem_cn":"全村得知一大笔钱已经丢失。","explanation_cn":"过去完成被动 had been + 过去分词。✓ a large sum of money had been lost 一大笔钱已丢失。✗ had lost:主动;✗ lost:一般过去主动;✗ was losing:过去进行主动。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',5,'am2_l45_gp3','choice','{"stem":"\"I can''t find my bag. It must ___ stolen.\"(对过去推测 + 被动:一定被偷了)","options":["have","have been","been","be"],"answer_index":1,"stem_cn":"我找不到包了,一定是被偷了。","explanation_cn":"对过去的推测 + 被动:must have been + 过去分词。✓ It must have been stolen 它一定被偷了。✗ be:那是\"必须被…\"(对现在);✗ been:缺 have;✗ have:缺 been。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',5,'am2_l45_gp3','choice','{"stem":"\"Sam was sure the wallet must ___ found by a villager.\"(对过去推测 + 被动)","options":["be","been","has","have been"],"answer_index":3,"stem_cn":"萨姆确信钱包一定被某个村民捡到了。","explanation_cn":"对过去的推测 + 被动:must have been + 过去分词。✓ must have been found 一定被捡到了。✗ be:对现在的\"必须被…\";✗ been:缺 have;✗ has:此处用 have been。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',5,'am2_l45_gp3','choice','{"stem":"\"This ___ paid for at once.\"(情态 + 被动:必须被付款)","options":["must be","is must","must have","must"],"answer_index":0,"stem_cn":"这必须马上付款。","explanation_cn":"\"必须被(付款)\"用 must be + 过去分词。✓ This must be paid for 这必须被付款。✗ must:缺 be;✗ must have:那是对过去推测;✗ is must:语序错。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',5,'am2_l45_gp3','choice','{"stem":"\"The window is broken; it must ___ broken by the boys.\"(对过去推测 + 被动)","options":["be","have been","been","has"],"answer_index":1,"stem_cn":"窗户碎了,一定是被男孩们打碎的。","explanation_cn":"对过去的推测 + 被动:must have been + 过去分词。✓ it must have been broken 一定是被打碎的。✗ be:对现在;✗ been:缺 have;✗ has:此处用 have been。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',5,'am2_l45_gp4','choice','{"stem":"把 \"Someone had sent the parcel\" 改成被动:The parcel ___.(主动变被动)","options":["had been sent","sent","had sent","has sent"],"answer_index":0,"stem_cn":"包裹被(某人)寄出。","explanation_cn":"主动 someone had sent → 被动 had been sent(过去完成被动)。✓ The parcel had been sent 包裹被寄出。✗ had sent:仍是主动;✗ has sent:现在完成主动;✗ sent:一般过去主动。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',5,'am2_l45_gp4','choice','{"stem":"把 \"The police arrested the thief\" 改成被动:The thief ___ by the police.(主动变被动)","options":["has arrested","arrests","arrested","was arrested"],"answer_index":3,"stem_cn":"小偷被警察逮捕。","explanation_cn":"主动 the police arrested → 被动 was arrested(一般过去被动)。✓ The thief was arrested 小偷被逮捕。✗ arrested:仍是主动;✗ has arrested:现在完成主动;✗ arrests:现在主动。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',5,'am2_l45_gp5','choice','{"stem":"\"The wallet must have been found ___ one of the villagers.\"(被动句里动作的执行者前用哪个介词)","options":["of","by","with","from"],"answer_index":1,"stem_cn":"钱包一定是被某个村民捡到的。","explanation_cn":"被动句里动作的执行者用 by 引出。✓ found by one of the villagers 被村民捡到。✗ with:表工具;✗ from:表来源;✗ of:不表执行者。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',5,'am2_l45_gp5','choice','{"stem":"\"This bridge was built ___ a famous engineer.\"(被动句里动作的执行者前用哪个介词)","options":["by","for","from","with"],"answer_index":0,"stem_cn":"这座桥是由一位著名工程师建造的。","explanation_cn":"被动句里动作的执行者用 by 引出。✓ built by a famous engineer 由工程师建造。✗ with:表工具;✗ from:表来源;✗ for:表目的。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',5,'am2_l45_gp6','choice','{"stem":"\"Sam lost his wallet ___ his savings to the post office.\"(在…的时候,连词后直接用 -ing)","options":["while taken","while took","while taking","while take"],"answer_index":2,"stem_cn":"萨姆在把存款送往邮局时丢了钱包。","explanation_cn":"\"在…的时候\",连词 while 后可直接用 -ing。✓ while taking his savings 在送存款时。✗ while took:while 后不接过去式;✗ while take:不接原形;✗ while taken:不接过去分词。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',5,'am2_l45_gp6','choice','{"stem":"\"___ the road, be careful of cars.\"(在…的时候,连词后直接用 -ing)","options":["While crossing","While to cross","While cross","While crossed"],"answer_index":0,"stem_cn":"过马路时要当心车。","explanation_cn":"\"在…的时候\",while 后直接用 -ing。✓ While crossing the road 过马路时。✗ While cross:不接原形;✗ While crossed:不接过去分词(非被动);✗ While to cross:不接不定式。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',5,'am2_l45_gp7','choice','{"stem":"\"___, all Sam''s money was paid back.\"(最后,终于)","options":["At time","By time","On time","In time"],"answer_index":3,"stem_cn":"最后,萨姆全部的钱都还回来了。","explanation_cn":"in time 在此表\"最后、终于\"。✓ In time, all his money was paid back 最后钱都还回来了。✗ On time:准时;✗ At time / By time:不是固定短语。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',5,'am2_l45_gp8','choice','{"stem":"\"A large ___ of money had been lost.\"(一大笔钱)","options":["number","group","sum","piece"],"answer_index":2,"stem_cn":"一大笔钱丢失了。","explanation_cn":"\"一大笔钱\"用 a large sum of money。✓ a large sum of money 一大笔钱。✗ number:接可数复数;✗ piece / group:不与 money 这样搭配。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',5,'am2_l45_gp8','choice','{"stem":"\"All Sam''s money was paid back ___ this way.\"(用这种方式)","options":["in","on","by","with"],"answer_index":0,"stem_cn":"萨姆全部的钱都用这种方式还了回来。","explanation_cn":"\"用这种方式\"用 in this way。✓ paid back in this way 用这种方式还钱。✗ by / with / on:不与 this way 构成这个固定短语。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',6,NULL,'choice','{"stem":"美语里\"邮政编码\"常说:","options":["post number","zip code","mail code","postcode"],"answer_index":1,"explanation_cn":"美语\"邮政编码\"常说 zip code;英式说 postcode。✓ my zip code 我的邮编。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',6,NULL,'choice','{"stem":"美语里\"钞票(纸币)\"常说:","options":["paper money","note","bill","cash slip"],"answer_index":2,"explanation_cn":"美语\"钞票(纸币)\"常说 bill;英式说 note。✓ a ten-dollar bill 一张十美元钞票。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',6,NULL,'choice','{"stem":"conscience 的意思是:","options":["意识丧失","良心,道德心","礼貌","知识"],"answer_index":1,"explanation_cn":"conscience = 良心、道德心。✓ a clear conscience 问心无愧。\n顺带记:知识 = knowledge;意识丧失 = unconsciousness;礼貌 = politeness."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',6,NULL,'choice','{"stem":"wallet 的意思是:","options":["背包","口袋","钱包,皮夹","钱箱"],"answer_index":2,"explanation_cn":"wallet = 钱包、皮夹。✓ lost his wallet 丢了钱包。\n顺带记:背包 = backpack;口袋 = pocket;钱箱 = cashbox."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',6,NULL,'choice','{"stem":"savings 的意思是:","options":["存款,积蓄","零钱","工资","债务"],"answer_index":0,"explanation_cn":"savings = 存款、积蓄。✓ taking his savings 送存款。\n顺带记:工资 = salary;债务 = debt;零钱 = change."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',6,NULL,'choice','{"stem":"villager 的意思是:","options":["农民","邻居","市民","村民"],"answer_index":3,"explanation_cn":"villager = 村民。✓ one of the villagers 某个村民。\n顺带记:市民 = citizen;农民 = farmer;邻居 = neighbor."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',7,NULL,'cloze','{"stem":"第 1 空","context":"Sam, the local butcher, lost his wallet while ___1___ his savings to the post office. He felt sure it ___2___ found by a villager. Months later the wallet ___3___ returned with half the money and a note. In time, all his money ___4___ paid back.","blank_no":1,"options":["taking","take","took","to take"],"answer_index":0,"explanation_cn":"\"在…的时候\",while 后直接用 -ing。✓ while taking his savings 在送存款时。\n✗ take / took / to take:while 后用 -ing。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',7,NULL,'cloze','{"stem":"第 2 空","context":"Sam, the local butcher, lost his wallet while ___1___ his savings to the post office. He felt sure it ___2___ found by a villager. Months later the wallet ___3___ returned with half the money and a note. In time, all his money ___4___ paid back.","blank_no":2,"options":["must have been","must be","must have","has been"],"answer_index":0,"explanation_cn":"对过去的推测 + 被动:must have been + 过去分词。✓ it must have been found 它一定被捡到了。\n✗ must be:对现在;✗ must have:缺 been;✗ has been:缺推测语气。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',7,NULL,'cloze','{"stem":"第 3 空","context":"Sam, the local butcher, lost his wallet while ___1___ his savings to the post office. He felt sure it ___2___ found by a villager. Months later the wallet ___3___ returned with half the money and a note. In time, all his money ___4___ paid back.","blank_no":3,"options":["was","is","has","does"],"answer_index":0,"explanation_cn":"一般过去被动 was + 过去分词。✓ the wallet was returned 钱包被送还。\n✗ is:现在;✗ has / does:不构成过去被动。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',7,NULL,'cloze','{"stem":"第 4 空","context":"Sam, the local butcher, lost his wallet while ___1___ his savings to the post office. He felt sure it ___2___ found by a villager. Months later the wallet ___3___ returned with half the money and a note. In time, all his money ___4___ paid back.","blank_no":4,"options":["was","is","has","does"],"answer_index":0,"explanation_cn":"一般过去被动 was + 过去分词。✓ all his money was paid back 钱都被还回。\n✗ is:现在;✗ has / does:不构成过去被动。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',8,NULL,'choice','{"stem":"How did Sam Benton lose his wallet?","options":["It was stolen at the market","He dropped it while taking his savings to the post office","A villager took it from his shop","He left it at home"],"answer_index":1,"explanation_cn":"课文说 had lost his wallet while taking his savings to the post office,他送存款途中丢了钱包。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',8,NULL,'choice','{"stem":"What was inside the wallet when it came back the first time?","options":["Half the lost money and a note","A different wallet","Nothing at all","All the money"],"answer_index":0,"explanation_cn":"课文说钱包里有丢失钱款的一半,还附着一张字条。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',8,NULL,'choice','{"stem":"What did the last note say?","options":["''I am 50 percent a thief.''","''Sorry, I spent it all.''","''I am 100 percent honest now!''","''Keep the money.''"],"answer_index":2,"explanation_cn":"课文结尾最后一张字条写 I am 100 percent honest now!。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',9,NULL,'choice','{"stem":"你想说\"钱包一定是被某个村民捡到了\"(对过去推测 + 被动:must have been + 过去分词):","options":["The wallet must have found by a villager.","The wallet must found by a villager.","The wallet must be found by a villager.","The wallet must have been found by a villager."],"answer_index":3,"explanation_cn":"对过去的推测 + 被动用 must have been + 过去分词。✓ The wallet must have been found by a villager. 场合:推测过去某事一定发生了(被动)。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',9,NULL,'choice','{"stem":"你想说\"这座桥建于1942年\"(一般过去被动:was + 过去分词):","options":["This bridge was build in 1942.","This bridge was built in 1942.","This bridge built in 1942.","This bridge is built in 1942."],"answer_index":1,"explanation_cn":"一般过去被动 was + 过去分词。✓ This bridge was built in 1942. 场合:说某物过去被做成/建成。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',9,NULL,'choice','{"stem":"你想说\"小偷被警察抓住了\"(被动 + by 引出执行者):","options":["The thief was arrested by the police.","The thief arrested by the police.","The thief was arrested with the police.","The thief was arrest by the police."],"answer_index":0,"explanation_cn":"被动句用 by 引出动作的执行者。✓ The thief was arrested by the police. 场合:说某人被谁做了某事。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',10,NULL,'choice','{"stem":"conscience 的意思是:","options":["知识","习惯","良心,道德心","勇气"],"answer_index":2,"explanation_cn":"conscience = 良心、道德心。✓ a clear conscience 问心无愧。\n顺带记:知识 = knowledge;勇气 = courage;习惯 = habit."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',10,NULL,'choice','{"stem":"savings 的意思是:","options":["债务","工资","罚款","存款,积蓄"],"answer_index":3,"explanation_cn":"savings = 存款、积蓄。✓ his savings 他的存款。\n顺带记:工资 = salary;债务 = debt;罚款 = fine."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',10,NULL,'choice','{"stem":"\"The wallet must ___ found by a villager.\"(对过去推测 + 被动)","options":["have been","has","been","be"],"answer_index":0,"stem_cn":"钱包一定是被某个村民捡到了。","explanation_cn":"对过去的推测 + 被动:must have been + 过去分词。✓ must have been found 一定被捡到了。\n✗ be:对现在的\"必须被…\";✗ been:缺 have;✗ has:此处用 have been。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',10,NULL,'choice','{"stem":"\"This bridge ___ in 1942.\"(一般过去被动)","options":["built","is built","was built","builds"],"answer_index":2,"stem_cn":"这座桥建于1942年。","explanation_cn":"一般过去被动 was + 过去分词。✓ This bridge was built in 1942 桥建于1942年。\n✗ built:主动;✗ builds:现在主动;✗ is built:现在被动,与 1942 不符。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',10,NULL,'choice','{"stem":"\"A thief, yes, but only 50 percent a thief!\" 这句话的意思是:","options":["小偷被抓了50次。","是个小偷,但只是个50%的小偷!","有50个小偷。","一个小偷偷了50元。"],"answer_index":1,"explanation_cn":"A thief, yes, but only 50 percent a thief! 意思是\"是个小偷,是的,但只是个50%的小偷!\"——只还了一半钱的自嘲。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',10,NULL,'choice','{"stem":"\"In time, all Sam''s money was paid back.\" 这句话的意思是:","options":["最后,萨姆全部的钱都还回来了。","萨姆借了一笔钱。","萨姆按时付了钱。","萨姆的钱花光了。"],"answer_index":0,"explanation_cn":"In time, all Sam''s money was paid back. in time = \"最后、终于\",was paid back = 被还回,意思是\"最后,萨姆全部的钱都还回来了\"。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',10,NULL,'choice','{"stem":"Why did Sam think the wallet had been found by a villager?","options":["A villager told him","He saw someone pick it up","The whole village soon knew a large sum of money had been lost","The police found it"],"answer_index":2,"passage":"The whole village soon learnt that a large sum of money had been lost. Sam Benton, the local butcher, had lost his wallet while taking his savings to the post office. Sam was sure that the wallet must have been found by one of the villagers, but it was not returned to him. Three months passed, and then one morning, Sam found his wallet outside his front door. It had been wrapped up in newspaper and it contained half the money he had lost, together with a note which said: ''A thief, yes, but only 50 percent a thief!'' Two months later, some more money was sent to Sam with another note: ''Only 25 percent a thief now!'' In time, all Sam''s money was paid back in this way. The last note said: ''I am 100 percent honest now!''","explanation_cn":"课文说全村很快得知一大笔钱丢了,所以萨姆推测是村民捡到了。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',10,NULL,'choice','{"stem":"How was Sam''s money returned to him?","options":["He never got it back","Bit by bit, wrapped in newspaper with notes, until it was all paid back","All at once by the police","The post office refunded him"],"answer_index":1,"passage":"The whole village soon learnt that a large sum of money had been lost. Sam Benton, the local butcher, had lost his wallet while taking his savings to the post office. Sam was sure that the wallet must have been found by one of the villagers, but it was not returned to him. Three months passed, and then one morning, Sam found his wallet outside his front door. It had been wrapped up in newspaper and it contained half the money he had lost, together with a note which said: ''A thief, yes, but only 50 percent a thief!'' Two months later, some more money was sent to Sam with another note: ''Only 25 percent a thief now!'' In time, all Sam''s money was paid back in this way. The last note said: ''I am 100 percent honest now!''","explanation_cn":"课文说钱包和钱分几次用报纸包着、附字条送回,最后全部还清。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',10,NULL,'choice','{"stem":"How long after losing it did Sam first find his wallet?","options":["The next day","He never found it","A year later","Three months later, outside his front door"],"answer_index":3,"audio":"The whole village soon learnt that a large sum of money had been lost. Sam Benton, the local butcher, had lost his wallet while taking his savings to the post office. Sam was sure that the wallet must have been found by one of the villagers, but it was not returned to him. Three months passed, and then one morning, Sam found his wallet outside his front door. It had been wrapped up in newspaper and it contained half the money he had lost, together with a note which said: ''A thief, yes, but only 50 percent a thief!'' Two months later, some more money was sent to Sam with another note: ''Only 25 percent a thief now!'' In time, all Sam''s money was paid back in this way. The last note said: ''I am 100 percent honest now!''","explanation_cn":"课文说 Three months passed… Sam found his wallet outside his front door,3个月后在门外发现。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l45',10,NULL,'choice','{"stem":"What did the notes show about the thief over time?","options":["He gradually returned all the money and became ''100 percent honest''","He moved away","He was caught by the police","He kept all the money"],"answer_index":0,"audio":"The whole village soon learnt that a large sum of money had been lost. Sam Benton, the local butcher, had lost his wallet while taking his savings to the post office. Sam was sure that the wallet must have been found by one of the villagers, but it was not returned to him. Three months passed, and then one morning, Sam found his wallet outside his front door. It had been wrapped up in newspaper and it contained half the money he had lost, together with a note which said: ''A thief, yes, but only 50 percent a thief!'' Two months later, some more money was sent to Sam with another note: ''Only 25 percent a thief now!'' In time, all Sam''s money was paid back in this way. The last note said: ''I am 100 percent honest now!''","explanation_cn":"字条从\"50%小偷\"到\"25%小偷\"再到\"100%诚实\",说明他一点点把钱全还了。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l46',2,6,46,'Expensive and uncomfortable','既昂贵又受罪','动词/形容词 + 介词搭配(verb + to/at/for/with,复习 KS22)主考——belong/occur/confine to、astonished/surprised/arrive at、account/pay/wait for、agree/cope/satisfied with;so…that、admit + doing、be ordered to do / be confined to、a number of(辅考·课文①类)','当一架来自伦敦的飞机抵达悉尼机场时,工人们开始卸下装有服装的一批木箱。其中有只箱子特别重,谁也弄不清是怎么回事。突然,一个工人想到打开这只箱子看看。看到的情景使他大吃一惊——箱内有一个人正躺在一堆羊毛织品之上。他由于被人发现而感到非常吃惊,甚至都没有企图逃跑。此人被捕后,承认是在飞机离开伦敦前躲进箱里的。他经历了一次漫长而又难受的旅程,因为他在那木箱里闷了18个多小时。此人被责令交付旅费3500英镑,而正常票价才2000英镑!','{"q":"Listen and answer — What did the man in this story do?","options":["He hid in a wooden box to travel from London to Sydney for free","He stole a plane ticket","He worked at the airport","He shipped clothing"],"answer_index":0}'::jsonb,'{"title":"动词 + 介词:to / at / for / with 各有搭配","intro":"很多动词或形容词后面要跟固定的介词,换了介词意思就变。记住常见搭配:属于/想到/关在用 to;对…惊讶/到达/看用 at;说明/付款/等待用 for;同意/应付/满意用 with。全用本课句子举例。","table":{"headers":["搭配","例子"],"rows":[["belong to / occur to / confine to","It occurred to him.(他想到) / confined to the box(关在箱里)"],["astonished at / surprised at / arrive at","astonished at what he found(对所见吃惊)"],["account for / pay for / wait for","account for the fact(说明) / pay for the trip(付旅费)"],["agree with / cope with / satisfied with","I agree with you.(同意) / cope with it(应付)"],["admit + doing","admitted hiding in the box(承认藏箱里)"]]},"specialRules":[{"rule":"同一个动词换介词意思会变:see Tom(看见汤姆)≠ see to the dinner(负责做饭)。","mark":"换介词 = 换意思"},{"rule":"admit / finish / enjoy 等后面接动名词:admitted hiding(承认藏)、finished eating(吃完)。","mark":"admit + doing"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l46',1,NULL,'When a plane from London arrived at Sydney airport, workers began to unload a number of wooden boxes which contained clothing.','当一架来自伦敦的飞机抵达悉尼机场时,工人们开始卸下装有服装的一批木箱。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l46',2,NULL,'No one could account for the fact that one of the boxes was extremely heavy.','其中有只箱子特别重,谁也弄不清是怎么回事。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l46',3,NULL,'It suddenly occurred to one of the workers to open up the box.','突然,一个工人想到打开这只箱子看看。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l46',4,NULL,'He was astonished at what he found. A man was lying in the box on top of a pile of woollen goods.','看到的情景使他大吃一惊——箱内有一个人正躺在一堆羊毛织品之上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l46',5,NULL,'He was so surprised at being discovered that he did not even try to run away.','他由于被人发现而感到非常吃惊,甚至都没有企图逃跑。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l46',6,NULL,'After he was arrested, the man admitted hiding in the box before the plane left London.','此人被捕后,承认是在飞机离开伦敦前躲进箱里的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l46',7,NULL,'He had had a long and uncomfortable trip, for he had been confined to the wooden box for over eighteen hours.','他经历了一次漫长而又难受的旅程,因为他在那木箱里闷了18个多小时。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l46',8,NULL,'The man was ordered to pay £3,500 for the cost of the trip. The normal price of a ticket is £2,000!','此人被责令交付旅费3500英镑,而正常票价才2000英镑!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l46','unload','/ʌnˈloʊd/','v','卸(货)','unload a number of wooden boxes') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l46','extremely','/ɪkˈstriːmli/','adv','非常,极其','extremely heavy') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
