INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l46','account for','',NULL,'/əˈkaʊnt fɔːr/','No one could account for the heavy box.','谁也说不清那只重箱子。','How do you account for this?','你怎么解释这件事?') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l46','occur to sb','',NULL,'/əˈkɜːr tuː/','It occurred to one of the workers to open the box.','一个工人想到打开箱子。','A good idea occurred to me.','我想到一个好主意。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l46','be confined to','',NULL,'/kənˈfaɪnd tuː/','He had been confined to the box for over 18 hours.','他被关在箱子里18个多小时。','She was confined to bed for a week.','她卧床一周。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l46','admit + doing','',NULL,'/ədˈmɪt ˈduːɪŋ/','The man admitted hiding in the box.','这人承认藏在箱子里。','He admitted taking the money.','他承认拿了钱。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',5,'am2_l46_gp1','choice','{"stem":"\"This box ___ one of the passengers.\"(belong 后面用哪个介词)","options":["for","at","with","to"],"answer_index":3,"stem_cn":"这箱子属于其中一位乘客。","explanation_cn":"belong to 表\"属于\"。✓ This box belongs to a passenger 箱子属于一位乘客。✗ at / for / with:不与 belong 搭配这个意思。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',5,'am2_l46_gp1','choice','{"stem":"\"It suddenly occurred ___ a worker that the box was too heavy.\"(occur 后面用哪个介词)","options":["with","for","to","at"],"answer_index":2,"stem_cn":"一个工人突然想到这箱子太重了。","explanation_cn":"occur to sb 表\"某人想到\"。✓ It occurred to a worker 一个工人想到。✗ at / for / with:不与 occur 搭配这个意思。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',5,'am2_l46_gp1','choice','{"stem":"\"The man was confined ___ the wooden box for 18 hours.\"(confine 后面用哪个介词)","options":["with","for","at","to"],"answer_index":3,"stem_cn":"这人被关在木箱里18个小时。","explanation_cn":"be confined to 表\"被关在、被限制在\"。✓ confined to the box 被关在箱里。✗ at / for / with:不与 confine 搭配这个意思。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',5,'am2_l46_gp2','choice','{"stem":"\"He was astonished ___ what he found.\"(astonished 后面用哪个介词)","options":["to","for","at","with"],"answer_index":2,"stem_cn":"他对所看到的感到惊讶。","explanation_cn":"be astonished at 表\"对…感到惊讶\"。✓ astonished at what he found 对所见吃惊。✗ to / for / with:不与 astonished 搭配。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',5,'am2_l46_gp2','choice','{"stem":"\"He was so surprised ___ being discovered that he didn''t run.\"(surprised 后面用哪个介词)","options":["with","at","to","for"],"answer_index":1,"stem_cn":"他对被发现感到非常吃惊。","explanation_cn":"be surprised at 表\"对…感到吃惊\"。✓ surprised at being discovered 对被发现吃惊。✗ to / for / with:不与 surprised 搭配。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',5,'am2_l46_gp2','choice','{"stem":"\"The plane arrived ___ Sydney airport.\"(arrive 到达某地点用哪个介词)","options":["to","for","at","with"],"answer_index":2,"stem_cn":"飞机抵达悉尼机场。","explanation_cn":"arrive at 表\"到达(某地点)\"。✓ arrived at Sydney airport 抵达机场。✗ to:arrive 不接 to;✗ for / with:不搭。(到达城市用 arrive in)"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',5,'am2_l46_gp3','choice','{"stem":"\"No one could account ___ the fact that the box was so heavy.\"(account 后面用哪个介词)","options":["at","to","with","for"],"answer_index":3,"stem_cn":"谁也说不清箱子为何这么重。","explanation_cn":"account for 表\"说明(原因)\"。✓ account for the fact 说明这个事实。✗ to / at / with:不与 account 搭配这个意思。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',5,'am2_l46_gp3','choice','{"stem":"\"The man was ordered to pay £3,500 ___ the cost of the trip.\"(pay 为某事付款用哪个介词)","options":["at","for","with","to"],"answer_index":1,"stem_cn":"此人被责令支付3500英镑旅费。","explanation_cn":"pay for 表\"为…付款\"。✓ pay for the trip 付旅费。✗ to / at / with:不与 pay 搭配这个意思。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',5,'am2_l46_gp3','choice','{"stem":"\"She had to wait ___ him at the airport.\"(wait 后面用哪个介词)","options":["for","at","with","to"],"answer_index":0,"stem_cn":"她得在机场等他。","explanation_cn":"wait for 表\"等待\"。✓ wait for him 等他。✗ to / at / with:不与 wait 搭配这个意思。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',5,'am2_l46_gp4','choice','{"stem":"\"I don''t agree ___ you.\"(agree 后面用哪个介词)","options":["for","at","to","with"],"answer_index":3,"stem_cn":"我不同意你的看法。","explanation_cn":"agree with 表\"同意(某人)\"。✓ agree with you 同意你。✗ to / at / for:不与 agree 搭配这个意思。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',5,'am2_l46_gp4','choice','{"stem":"\"Poor Mary has so much to cope ___.\"(cope 后面用哪个介词)","options":["to","with","for","at"],"answer_index":1,"stem_cn":"可怜的玛丽有太多要应付。","explanation_cn":"cope with 表\"应付、对付\"。✓ cope with it 应付它。✗ to / at / for:不与 cope 搭配。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',5,'am2_l46_gp4','choice','{"stem":"\"I''m not satisfied ___ your work.\"(satisfied 后面用哪个介词)","options":["for","at","with","to"],"answer_index":2,"stem_cn":"我对你的工作不满意。","explanation_cn":"be satisfied with 表\"对…满意\"。✓ satisfied with your work 对你的工作满意。✗ to / at / for:不与 satisfied 搭配。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',5,'am2_l46_gp5','choice','{"stem":"\"He was ___ surprised at being discovered that he did not run away.\"(…得…以至于,后接形容词)","options":["so","too","very","such"],"answer_index":0,"stem_cn":"他被发现时太吃惊了,以至于没逃跑。","explanation_cn":"\"…得…以至于\",后接形容词用 so + adj + that。✓ so surprised that… 太吃惊以至于…。✗ such:后接名词;✗ very:不与 that 构成因果;✗ too:是\"太…(而不能)\"。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',5,'am2_l46_gp5','choice','{"stem":"\"It was ___ a heavy box that no one could lift it.\"(…得…以至于,后接 a+名词)","options":["so","too","very","such"],"answer_index":3,"stem_cn":"那箱子太重了,没人搬得动。","explanation_cn":"\"…得…以至于\",后接\"a + 名词\"用 such + a + n + that。✓ such a heavy box that… 太重的箱子以至于…。✗ so:后接形容词;✗ very / too:不构成此结构。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',5,'am2_l46_gp6','choice','{"stem":"\"The man admitted ___ in the box before the plane left.\"(admit 后面接动名词)","options":["hiding","hide","to hide","hid"],"answer_index":0,"stem_cn":"这人承认在飞机起飞前藏进了箱子。","explanation_cn":"admit 后面接动名词。✓ admitted hiding in the box 承认藏在箱里。✗ to hide:admit 不接不定式;✗ hide / hid:结构不对。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',5,'am2_l46_gp6','choice','{"stem":"\"He admitted ___ the money.\"(admit 后面接动名词)","options":["took","take","taking","to take"],"answer_index":2,"stem_cn":"他承认拿了钱。","explanation_cn":"admit 后面接动名词。✓ admitted taking the money 承认拿了钱。✗ to take:admit 不接不定式;✗ take / took:结构不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',5,'am2_l46_gp7','choice','{"stem":"\"The man ___ to pay £3,500.\"(被命令做某事,用被动 be + 过去分词)","options":["was order","was ordering","ordered","was ordered"],"answer_index":3,"stem_cn":"此人被责令支付3500英镑。","explanation_cn":"\"被命令做某事\"用被动 be + 过去分词(was ordered to do)。✓ The man was ordered to pay 此人被责令付款。✗ was order:缺过去分词;✗ ordered:是主动;✗ was ordering:过去进行主动。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',5,'am2_l46_gp8','choice','{"stem":"\"Workers unloaded ___ wooden boxes.\"(许多,后接可数名词复数)","options":["a great deal of","a number of","a little","much"],"answer_index":1,"stem_cn":"工人们卸下许多木箱。","explanation_cn":"\"许多\"接可数名词复数用 a number of。✓ a number of wooden boxes 许多木箱。✗ a great deal of / much:接不可数;✗ a little:接不可数且意思不符。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',6,NULL,'choice','{"stem":"美语里\"行李\"常说:","options":["luggage","baggage","packs","cases"],"answer_index":1,"explanation_cn":"美语\"行李\"常说 baggage;英式说 luggage。✓ check your baggage 托运行李。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',6,NULL,'choice','{"stem":"美语里\"毛衣\"常说:","options":["knit top","jumper","sweater","woolly"],"answer_index":2,"explanation_cn":"美语\"毛衣\"常说 sweater;英式说 jumper。✓ a wool sweater 一件羊毛衫。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',6,NULL,'choice','{"stem":"extremely 的意思是:","options":["偶尔","非常,极其","几乎不","仅仅"],"answer_index":1,"explanation_cn":"extremely = 非常、极其。✓ extremely heavy 特别重。\n顺带记:偶尔 = occasionally;几乎不 = hardly;仅仅 = only."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',6,NULL,'choice','{"stem":"astonish 的意思是:","options":["使疲惫","使害怕","使高兴","使惊讶"],"answer_index":3,"explanation_cn":"astonish = 使惊讶。✓ astonished at what he found 对所见吃惊。\n顺带记:使高兴 = please;使害怕 = frighten;使疲惫 = tire."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',6,NULL,'choice','{"stem":"confine 的意思是:","options":["移动","关在,限制在","扩大","释放"],"answer_index":1,"explanation_cn":"confine = 关在、限制在。✓ confined to the box 被关在箱里。\n顺带记:释放 = release;扩大 = expand;移动 = move."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',6,NULL,'choice','{"stem":"normal 的意思是:","options":["昂贵的","特殊的","错误的","正常的,通常的"],"answer_index":3,"explanation_cn":"normal = 正常的、通常的。✓ the normal price 正常票价。\n顺带记:昂贵的 = expensive;特殊的 = special;错误的 = wrong."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',7,NULL,'cloze','{"stem":"第 1 空","context":"When a plane arrived ___1___ Sydney airport, workers found a very heavy box. No one could account ___2___ its weight. A worker was astonished ___3___ what he found: a man inside! The man was ordered to pay ___4___ the trip.","blank_no":1,"options":["at","to","for","with"],"answer_index":0,"explanation_cn":"arrive at 表\"到达(某地点)\"。✓ arrived at Sydney airport 抵达机场。\n✗ to:arrive 不接 to;✗ for / with:不搭。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',7,NULL,'cloze','{"stem":"第 2 空","context":"When a plane arrived ___1___ Sydney airport, workers found a very heavy box. No one could account ___2___ its weight. A worker was astonished ___3___ what he found: a man inside! The man was ordered to pay ___4___ the trip.","blank_no":2,"options":["for","to","at","with"],"answer_index":0,"explanation_cn":"account for 表\"说明(原因)\"。✓ account for its weight 说明它为何这么重。\n✗ to / at / with:不与 account 搭配。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',7,NULL,'cloze','{"stem":"第 3 空","context":"When a plane arrived ___1___ Sydney airport, workers found a very heavy box. No one could account ___2___ its weight. A worker was astonished ___3___ what he found: a man inside! The man was ordered to pay ___4___ the trip.","blank_no":3,"options":["at","to","for","with"],"answer_index":0,"explanation_cn":"be astonished at 表\"对…感到惊讶\"。✓ astonished at what he found 对所见吃惊。\n✗ to / for / with:不与 astonished 搭配。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',7,NULL,'cloze','{"stem":"第 4 空","context":"When a plane arrived ___1___ Sydney airport, workers found a very heavy box. No one could account ___2___ its weight. A worker was astonished ___3___ what he found: a man inside! The man was ordered to pay ___4___ the trip.","blank_no":4,"options":["for","to","at","with"],"answer_index":0,"explanation_cn":"pay for 表\"为…付款\"。✓ pay for the trip 付旅费。\n✗ to / at / with:不与 pay 搭配这个意思。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',8,NULL,'choice','{"stem":"What did the workers unload from the plane at Sydney airport?","options":["Furniture","Live animals","Wooden boxes containing clothing","Cars"],"answer_index":2,"explanation_cn":"课文说 workers began to unload a number of wooden boxes which contained clothing,卸下装服装的木箱。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',8,NULL,'choice','{"stem":"What did a worker find inside the extremely heavy box?","options":["A man lying on a pile of woollen goods","Gold bars","Only clothing","Nothing unusual"],"answer_index":0,"explanation_cn":"课文说 A man was lying in the box on top of a pile of woollen goods。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',8,NULL,'choice','{"stem":"Why didn''t the man try to run away when discovered?","options":["He was tied up","He was asleep","He wanted to be caught","He was so surprised at being discovered"],"answer_index":3,"explanation_cn":"课文说 He was so surprised at being discovered that he did not even try to run away。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',9,NULL,'choice','{"stem":"你想说\"谁也说不清这个事实\"(说明原因用 account for):","options":["No one could account the fact.","No one could account at the fact.","No one could account for the fact.","No one could account with the fact."],"answer_index":2,"explanation_cn":"account for 表\"说明(原因)\",后接 for。✓ No one could account for the fact. 场合:说没人能解释某事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',9,NULL,'choice','{"stem":"你想说\"一个工人突然想到打开箱子\"(想起某事用 occur to):","options":["It occurred at a worker to open the box.","It occurred to a worker to open the box.","It occurred for a worker to open the box.","It occurred a worker to open the box."],"answer_index":1,"explanation_cn":"occur to sb 表\"某人想到\",后接 to。✓ It occurred to a worker to open the box. 场合:说某人突然想到做某事。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',9,NULL,'choice','{"stem":"你想说\"他被关在箱子里18个小时\"(关在…用 be confined to):","options":["He was confined at the box for 18 hours.","He was confined the box for 18 hours.","He was confined for the box for 18 hours.","He was confined to the box for 18 hours."],"answer_index":3,"explanation_cn":"be confined to 表\"被关在\",后接 to。✓ He was confined to the box for 18 hours. 场合:说某人被关/困在某处。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',10,NULL,'choice','{"stem":"astonish 的意思是:","options":["使惊讶","使疲惫","使生气","使高兴"],"answer_index":0,"explanation_cn":"astonish = 使惊讶。✓ astonished at 对…吃惊。\n顺带记:使高兴 = please;使生气 = anger;使疲惫 = tire."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',10,NULL,'choice','{"stem":"normal 的意思是:","options":["危险的","昂贵的","罕见的","正常的,通常的"],"answer_index":3,"explanation_cn":"normal = 正常的、通常的。✓ the normal price 正常票价。\n顺带记:昂贵的 = expensive;罕见的 = rare;危险的 = dangerous."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',10,NULL,'choice','{"stem":"\"No one could account ___ the fact.\"(说明原因)","options":["for","at","with","to"],"answer_index":0,"stem_cn":"谁也说不清这个事实。","explanation_cn":"account for 表\"说明(原因)\",后接 for。✓ account for the fact 说明这个事实。\n✗ to / at / with:不与 account 搭配。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',10,NULL,'choice','{"stem":"\"He was astonished ___ what he found.\"(对…感到惊讶)","options":["for","at","to","with"],"answer_index":1,"stem_cn":"他对所看到的感到惊讶。","explanation_cn":"be astonished at 表\"对…感到惊讶\",后接 at。✓ astonished at what he found 对所见吃惊。\n✗ to / for / with:不与 astonished 搭配。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',10,NULL,'choice','{"stem":"\"He was so surprised at being discovered that he did not try to run away.\" 这句话的意思是:","options":["他被发现时太吃惊了,以至于没试图逃跑。","他假装很吃惊。","他发现后很高兴。","他被发现后立刻逃跑了。"],"answer_index":0,"explanation_cn":"He was so surprised at being discovered that he did not try to run away. so…that = \"如此…以至于\",意思是\"他被发现时太吃惊了,以至于没试图逃跑\"。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',10,NULL,'choice','{"stem":"\"He had been confined to the box for over eighteen hours.\" 这句话的意思是:","options":["他在箱子上待了18小时。","他18小时前离开了箱子。","他花了18小时做箱子。","他被关在箱子里18个多小时。"],"answer_index":3,"explanation_cn":"He had been confined to the box for over eighteen hours. be confined to = 被关在,意思是\"他被关在箱子里18个多小时\"。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',10,NULL,'choice','{"stem":"Why was one of the boxes extremely heavy?","options":["A man was hiding inside it","It was made of stone","It was full of gold","It held machinery"],"answer_index":0,"passage":"When a plane from London arrived at Sydney airport, workers began to unload a number of wooden boxes which contained clothing. No one could account for the fact that one of the boxes was extremely heavy. It suddenly occurred to one of the workers to open up the box. He was astonished at what he found. A man was lying in the box on top of a pile of woollen goods. He was so surprised at being discovered that he did not even try to run away. After he was arrested, the man admitted hiding in the box before the plane left London. He had had a long and uncomfortable trip, for he had been confined to the wooden box for over eighteen hours. The man was ordered to pay £3,500 for the cost of the trip. The normal price of a ticket is £2,000!","explanation_cn":"课文说箱子特别重是因为里面藏了一个人(A man was lying in the box)。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',10,NULL,'choice','{"stem":"How much was the man ordered to pay, and how did it compare to a normal ticket?","options":["£500 — less than a ticket","£3,500 — far more than the normal £2,000 ticket","Nothing at all","£2,000 — the same as a ticket"],"answer_index":1,"passage":"When a plane from London arrived at Sydney airport, workers began to unload a number of wooden boxes which contained clothing. No one could account for the fact that one of the boxes was extremely heavy. It suddenly occurred to one of the workers to open up the box. He was astonished at what he found. A man was lying in the box on top of a pile of woollen goods. He was so surprised at being discovered that he did not even try to run away. After he was arrested, the man admitted hiding in the box before the plane left London. He had had a long and uncomfortable trip, for he had been confined to the wooden box for over eighteen hours. The man was ordered to pay £3,500 for the cost of the trip. The normal price of a ticket is £2,000!","explanation_cn":"课文说他被责令付3500英镑,而正常票价才2000英镑,比买票还贵。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',10,NULL,'choice','{"stem":"When had the man hidden in the box?","options":["During the flight","At Sydney airport","After landing","Before the plane left London"],"answer_index":3,"audio":"When a plane from London arrived at Sydney airport, workers began to unload a number of wooden boxes which contained clothing. No one could account for the fact that one of the boxes was extremely heavy. It suddenly occurred to one of the workers to open up the box. He was astonished at what he found. A man was lying in the box on top of a pile of woollen goods. He was so surprised at being discovered that he did not even try to run away. After he was arrested, the man admitted hiding in the box before the plane left London. He had had a long and uncomfortable trip, for he had been confined to the wooden box for over eighteen hours. The man was ordered to pay £3,500 for the cost of the trip. The normal price of a ticket is £2,000!","explanation_cn":"课文说 the man admitted hiding in the box before the plane left London,飞机离开伦敦前躲进箱里。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l46',10,NULL,'choice','{"stem":"Why is the story called ''Expensive and uncomfortable''?","options":["The box was made of gold","The flight was delayed","He paid more than a ticket and was cramped in a box for 18 hours","The clothing was costly"],"answer_index":2,"audio":"When a plane from London arrived at Sydney airport, workers began to unload a number of wooden boxes which contained clothing. No one could account for the fact that one of the boxes was extremely heavy. It suddenly occurred to one of the workers to open up the box. He was astonished at what he found. A man was lying in the box on top of a pile of woollen goods. He was so surprised at being discovered that he did not even try to run away. After he was arrested, the man admitted hiding in the box before the plane left London. He had had a long and uncomfortable trip, for he had been confined to the wooden box for over eighteen hours. The man was ordered to pay £3,500 for the cost of the trip. The normal price of a ticket is £2,000!","explanation_cn":"标题 Expensive and uncomfortable 指他付得比机票还多(昂贵),又在箱里闷了18小时(受罪)。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l47',2,6,47,'A thirsty ghost','嗜酒的鬼魂','综合复习(Review KS36–45)主考——must have done(对过去推测,课文核心)、被动 had been done(KS45)、间接引语 tell/say that(KS39)、be going to(KS36)、将来完成时 will have done(KS37)、虚拟条件(KS40)、as if + 过去完成(KS38)、be able to(KS43)——以本课''嗜酒鬼魂''故事里出现的结构为重点串讲','伊恩·汤普森先生最近买下的一家小酒馆又要出售了,因为那里闹鬼。他告诉我,有天夜里怎么也睡不着,因为听到酒吧里传来一阵奇怪的响声。第二天早上,他发现门被椅子堵上了,家具也被挪动过;虽然睡前把灯关了,早晨灯却都亮着。他还说发现了5个空威士忌瓶,这肯定是鬼魂头天晚上喝的。当我暗示说一定是村里有人来喝免费酒时,汤普森先生摇了摇头。村里人已经告诉他,即使他把酒馆白送人,他们也不要。','{"q":"Listen and answer — What evidence is there of a ghost?","options":["Strange noises, blocked doors, moved furniture, and empty whisky bottles","A photograph of the ghost","The ghost''s footprints","A recorded voice"],"answer_index":0}'::jsonb,'{"title":"综合复习:对过去推测 must have done + 各时态回顾","intro":"本课把 L36–45 学过的结构串起来复习,重点是''对过去的推测''——用 must have + 过去分词,表示''过去一定发生了某事''。顺带回顾被动(had been done)、间接引语(tell/say that)、be going to、将来完成时、虚拟条件等。全用本课句子举例。","table":{"headers":["结构","例子"],"rows":[["对过去推测 must have done","The ghost must have drunk the whisky.(一定喝了)"],["过去完成被动 had been done","The doors had been blocked by chairs.(被堵住)"],["间接引语 tell/say that","He told me that he could not sleep.(告诉我)"],["be going to","He is going to sell the pub.(打算卖)"],["将来完成时 will have done","Workers will have completed the roads.(将已完成)"]]},"specialRules":[{"rule":"对过去的推测用 must have + 过去分词:The ghost must have drunk(鬼魂一定喝了)、villagers must have come in(村民一定进来过)。","mark":"must have done = 过去一定…"},{"rule":"过去某次''终于做成''用 was/were able to,不用 could:he was able to sleep again(终于又能睡了)。","mark":"成功做成用 was able to"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l47',1,NULL,'A public house which was recently bought by Mr. Ian Thompson is up for sale. Mr. Thompson is going to sell it because it is haunted.','伊恩·汤普森先生最近买下的一家小酒馆又要出售了,因为那里闹鬼。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l47',2,NULL,'He told me that he could not go to sleep one night because he heard a strange noise coming from the bar.','他告诉我,有天夜里怎么也睡不着,因为听到酒吧里传来一阵奇怪的响声。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l47',3,NULL,'The next morning, he found that the doors had been blocked by chairs and the furniture had been moved.','第二天早上,他发现门被椅子堵上了,家具也被挪动过。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l47',4,NULL,'Though Mr. Thompson had turned the lights off before he went to bed, they were on in the morning.','虽然汤普森睡前把灯关了,早晨灯却都亮着。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l47',5,NULL,'He also said that he had found five empty whisky bottles which the ghost must have drunk the night before.','他还说发现了5个空威士忌瓶,这肯定是鬼魂头天晚上喝的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l47',6,NULL,'When I suggested that some villagers must have come in for a free drink, Mr. Thompson shook his head.','当我暗示说一定是村里有人来喝免费酒时,汤普森先生摇了摇头。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l47',7,NULL,'The villagers have told him that they will not accept the pub even if he gives it away.','村里人已经告诉他,即使他把酒馆白送人,他们也不要。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
