INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l47','apartment','flat','公寓;美语 apartment,英式 flat(房产/出售场景)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
