INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l47','must have + 过去分词','',NULL,'/mʌst həv/','The ghost must have drunk the whisky.','鬼魂一定把威士忌喝了。','Some villagers must have come in.','一定是有村民进来过。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l47','be going to','',NULL,'/bi ˈɡoʊɪŋ tuː/','He is going to sell the pub.','他打算卖掉酒馆。','It is going to rain.','要下雨了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l47','up for sale','',NULL,'/ʌp fɔːr seɪl/','The pub is up for sale.','这家酒馆正在出售。','Their house is up for sale.','他们的房子正在出售。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l47','shake one''s head','',NULL,'/ʃeɪk ... hed/','Mr. Thompson shook his head.','汤普森摇了摇头。','She shook her head and said no.','她摇头说不。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',5,'am2_l47_gp1','choice','{"stem":"\"The ghost ___ the whisky — five bottles are empty!\"(对过去的推测:一定喝了)","options":["drank","must drinking","must have drunk","must drink"],"answer_index":2,"stem_cn":"鬼魂一定把威士忌喝了——五个瓶子都空了!","explanation_cn":"对过去的推测用 must have + 过去分词。✓ The ghost must have drunk 鬼魂一定喝了。✗ must drink:那是对现在;✗ must drinking:结构错;✗ drank:缺推测语气。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',5,'am2_l47_gp1','choice','{"stem":"\"Some villagers ___ in for a free drink last night.\"(对过去的推测:一定进来过)","options":["must have come","come","must came","must come"],"answer_index":0,"stem_cn":"一定是有村民昨晚进来蹭酒喝了。","explanation_cn":"对过去的推测用 must have + 过去分词。✓ villagers must have come in 村民一定进来过。✗ must come:对现在;✗ must came:结构错;✗ come:缺推测语气。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',5,'am2_l47_gp1','choice','{"stem":"\"The lights are on; someone ___ them on.\"(对过去的推测:一定开了)","options":["turned","must turn","must have turned","must turning"],"answer_index":2,"stem_cn":"灯亮着,一定是有人开的。","explanation_cn":"对过去的推测用 must have + 过去分词。✓ someone must have turned them on 一定有人开了灯。✗ must turn:对现在;✗ must turning:结构错;✗ turned:缺推测语气。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',5,'am2_l47_gp1','choice','{"stem":"\"He looks exhausted; he ___ hard all night.\"(对过去的推测:一定干了)","options":["must working","must work","worked","must have worked"],"answer_index":3,"stem_cn":"他看起来累坏了,一定是干了一整夜。","explanation_cn":"对过去的推测用 must have + 过去分词。✓ he must have worked hard 他一定干得很卖力。✗ must work:对现在;✗ must working:结构错;✗ worked:缺推测语气。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',5,'am2_l47_gp2','choice','{"stem":"\"The next morning, the doors ___ by chairs.\"(过去完成被动:被堵住)","options":["were blocking","blocked","had been blocked","had blocked"],"answer_index":2,"stem_cn":"第二天早上,门被椅子堵住了。","explanation_cn":"过去完成的被动:had been + 过去分词。✓ the doors had been blocked 门被堵住了。✗ had blocked:主动;✗ blocked:一般过去主动;✗ were blocking:过去进行主动。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',5,'am2_l47_gp2','choice','{"stem":"\"The furniture ___ during the night.\"(过去完成被动:被挪动)","options":["moved","was moving","had moved","had been moved"],"answer_index":3,"stem_cn":"家具在夜里被挪动过。","explanation_cn":"过去完成被动:had been + 过去分词。✓ the furniture had been moved 家具被挪动。✗ had moved:主动;✗ moved:一般过去主动;✗ was moving:过去进行主动。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',5,'am2_l47_gp2','choice','{"stem":"\"The pub ___ by Mr. Thompson recently.\"(一般过去被动:被买下)","options":["was bought","buys","bought","had buying"],"answer_index":0,"stem_cn":"这家酒馆最近被汤普森先生买下。","explanation_cn":"一般过去被动:was + 过去分词。✓ The pub was bought by Mr. Thompson 酒馆被买下。✗ bought:主动;✗ buys:现在主动;✗ had buying:结构错。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',5,'am2_l47_gp3','choice','{"stem":"\"He ___ me that he could not sleep.\"(告诉某人,后面带宾语)","options":["spoke","told","talked","said"],"answer_index":1,"stem_cn":"他告诉我他睡不着。","explanation_cn":"\"告诉某人某事\"用 tell(后接人)。✓ He told me that… 他告诉我…。✗ said:后面不直接接人;✗ spoke / talked:不接 that 从句转述内容。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',5,'am2_l47_gp3','choice','{"stem":"\"He also ___ that he had found five empty bottles.\"(不带宾语,直接接从句)","options":["said","talked","spoke","told"],"answer_index":0,"stem_cn":"他还说他发现了五个空瓶。","explanation_cn":"不带人、直接接内容,用 say。✓ He said that he had found… 他说他发现…。✗ told:后面要带人;✗ spoke / talked:不接 that 从句转述内容。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',5,'am2_l47_gp3','choice','{"stem":"\"He said that the doors ___ blocked by chairs.\"(间接引语 + 时态后移的被动)","options":["are","have been","had been","were being"],"answer_index":2,"stem_cn":"他说门被椅子堵住了。","explanation_cn":"间接引语里时态后移,被动变过去完成:had been + 过去分词。✓ the doors had been blocked 门被堵住。✗ have been:未后移;✗ are:不是被动过去;✗ were being:意思不符。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',5,'am2_l47_gp4','choice','{"stem":"\"Mr. Thompson ___ sell the pub because it is haunted.\"(表将来的打算、计划)","options":["went to","is going to","is go to","goes to"],"answer_index":1,"stem_cn":"汤普森打算卖掉酒馆,因为它闹鬼。","explanation_cn":"表将来的打算、计划用 be going to。✓ He is going to sell the pub 他打算卖酒馆。✗ goes to / went to:不表打算;✗ is go to:结构错。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',5,'am2_l47_gp4','choice','{"stem":"\"She ___ swim across the Channel tomorrow.\"(表将来的打算、计划)","options":["is going to","went to","is go to","goes to"],"answer_index":0,"stem_cn":"她打算明天横渡海峡。","explanation_cn":"表将来的打算、计划用 be going to。✓ She is going to swim across the Channel 她打算横渡海峡。✗ goes to / went to:不表打算;✗ is go to:结构错。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',5,'am2_l47_gp5','choice','{"stem":"\"Workers ___ the new roads by the end of this year.\"(将来完成时:到…时已完成)","options":["have completed","will have completed","complete","will completing"],"answer_index":1,"stem_cn":"到今年底工人们将已修完新路。","explanation_cn":"将来完成时:到将来某时已完成,用 will have + 过去分词。✓ Workers will have completed the roads 到时路已修完。✗ will completing:结构错;✗ have completed:现在完成;✗ complete:一般现在。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',5,'am2_l47_gp5','choice','{"stem":"\"By next June, I ___ from college.\"(将来完成时:到…时已完成)","options":["graduate","have graduated","will have graduated","will graduating"],"answer_index":2,"stem_cn":"到明年6月,我将已大学毕业。","explanation_cn":"将来完成时 will have + 过去分词。✓ I will have graduated by next June 到明年6月我已毕业。✗ will graduating:结构错;✗ have graduated:现在完成;✗ graduate:一般现在。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',5,'am2_l47_gp6','choice','{"stem":"\"If the pub ___ cheaper, someone would buy it.\"(虚拟:if 从句用过去式)","options":["were","will be","was","is"],"answer_index":0,"stem_cn":"酒馆要是便宜些,就有人买了。","explanation_cn":"非真实条件:if 从句用过去式;be 一律用 were。✓ If the pub were cheaper 酒馆要是便宜些。✗ is:陈述事实;✗ was:虚拟里不用;✗ will be:if 从句不用 will。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',5,'am2_l47_gp6','choice','{"stem":"\"If I ___ you, I wouldn''t sell it.\"(虚拟:be 一律用这个特殊形式)","options":["be","am","were","was"],"answer_index":2,"stem_cn":"我要是你,就不会卖它。","explanation_cn":"非真实条件里 be 一律用 were,连 I 也用 were。✓ If I were you 我要是你。✗ was:虚拟里不用;✗ am:陈述事实;✗ be:缺变化。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',5,'am2_l47_gp7','choice','{"stem":"\"He talked ___ he had seen a ghost.\"(表''好像…似的'',后接过去完成)","options":["than","so","like","as if"],"answer_index":3,"stem_cn":"他说得好像见过鬼似的。","explanation_cn":"\"好像…似的\"用 as if,后接过去完成表与事实不符。✓ as if he had seen a ghost 好像见过鬼。✗ like:后不接 if 从句;✗ so / than:不构成\"好像\"。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',5,'am2_l47_gp8','choice','{"stem":"\"After the ghost left, he ___ sleep again.\"(过去某次''终于做到了'',强调成功结果)","options":["was able to","could","can","will"],"answer_index":0,"stem_cn":"鬼魂走后,他终于又能睡了。","explanation_cn":"过去某次''终于成功做到''用 was able to,不用 could。✓ he was able to sleep again 他终于又能睡了。✗ could:表成功做成时不用;✗ can:现在;✗ will:将来。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',6,NULL,'choice','{"stem":"美语里\"酒馆\"常说:","options":["pub","drink house","tavern house","bar"],"answer_index":3,"explanation_cn":"美语\"酒馆\"常说 bar;英式说 pub(public house)。✓ go to a bar 去酒馆。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',6,NULL,'choice','{"stem":"美语里\"威士忌\"的拼写常是:","options":["whiskey","wiskey","whicky","whisky"],"answer_index":0,"explanation_cn":"美语拼作 whiskey;英式/苏格兰拼作 whisky。✓ a glass of whiskey 一杯威士忌。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',6,NULL,'choice','{"stem":"thirsty 的意思是:","options":["疲惫的","害怕的","口渴的;贪杯的","饥饿的"],"answer_index":2,"explanation_cn":"thirsty = 口渴的;贪杯的。✓ a thirsty ghost 嗜酒的鬼魂。\n顺带记:饥饿的 = hungry;疲惫的 = tired;害怕的 = afraid."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',6,NULL,'choice','{"stem":"haunt 的意思是:","options":["(鬼)来访,闹鬼","出售","装修","打扫"],"answer_index":0,"explanation_cn":"haunt = (鬼)来访、闹鬼。✓ it is haunted 那里闹鬼。\n顺带记:打扫 = clean;装修 = decorate;出售 = sell."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',6,NULL,'choice','{"stem":"accept 的意思是:","options":["购买","接受","拒绝","归还"],"answer_index":1,"explanation_cn":"accept = 接受。✓ will not accept the pub 不要这酒馆。\n顺带记:拒绝 = refuse;购买 = buy;归还 = return."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',6,NULL,'choice','{"stem":"furniture 的意思是:","options":["家具","衣服","餐具","工具"],"answer_index":0,"explanation_cn":"furniture = 家具。✓ the furniture had been moved 家具被挪动。\n顺带记:衣服 = clothes;餐具 = tableware;工具 = tools."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',7,NULL,'cloze','{"stem":"第 1 空","context":"Mr. Thompson ___1___ sell his pub because it is haunted. One morning he found the doors ___2___ by chairs. He said the ghost ___3___ five bottles of whisky. When I suggested villagers had done it, he shook his head — they ___4___ never accept the pub.","blank_no":1,"options":["is going to","goes to","went to","is go to"],"answer_index":0,"explanation_cn":"表将来的打算用 be going to。✓ He is going to sell his pub 他打算卖酒馆。\n✗ goes to / went to:不表打算;✗ is go to:结构错。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',7,NULL,'cloze','{"stem":"第 2 空","context":"Mr. Thompson ___1___ sell his pub because it is haunted. One morning he found the doors ___2___ by chairs. He said the ghost ___3___ five bottles of whisky. When I suggested villagers had done it, he shook his head — they ___4___ never accept the pub.","blank_no":2,"options":["had been blocked","had blocked","blocked","were blocking"],"answer_index":0,"explanation_cn":"过去完成被动:had been + 过去分词。✓ the doors had been blocked 门被堵住。\n✗ had blocked:主动;✗ blocked:一般过去主动;✗ were blocking:过去进行主动。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',7,NULL,'cloze','{"stem":"第 3 空","context":"Mr. Thompson ___1___ sell his pub because it is haunted. One morning he found the doors ___2___ by chairs. He said the ghost ___3___ five bottles of whisky. When I suggested villagers had done it, he shook his head — they ___4___ never accept the pub.","blank_no":3,"options":["must have drunk","must drink","must drank","drinks"],"answer_index":0,"explanation_cn":"对过去的推测用 must have + 过去分词。✓ the ghost must have drunk 鬼魂一定喝了。\n✗ must drink:对现在;✗ must drank:结构错;✗ drinks:缺推测语气。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',7,NULL,'cloze','{"stem":"第 4 空","context":"Mr. Thompson ___1___ sell his pub because it is haunted. One morning he found the doors ___2___ by chairs. He said the ghost ___3___ five bottles of whisky. When I suggested villagers had done it, he shook his head — they ___4___ never accept the pub.","blank_no":4,"options":["would","will","are","did"],"answer_index":0,"explanation_cn":"间接引语里将来 will 后移成 would。✓ they would never accept the pub 他们绝不会要酒馆。\n✗ will:未后移;✗ are / did:不合此处的将来转述。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',8,NULL,'choice','{"stem":"Why is Mr. Thompson going to sell the pub?","options":["Because it is haunted","Because it is too small","Because he needs money","Because it is far away"],"answer_index":0,"explanation_cn":"课文说 Mr. Thompson is going to sell it because it is haunted,因为闹鬼要卖。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',8,NULL,'choice','{"stem":"What did Mr. Thompson find the next morning?","options":["A broken window","The pub on fire","The doors blocked by chairs and the furniture moved","Nothing unusual"],"answer_index":2,"explanation_cn":"课文说 the doors had been blocked by chairs and the furniture had been moved。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',8,NULL,'choice','{"stem":"What did the five empty whisky bottles suggest to Mr. Thompson?","options":["They were always empty","The villagers had bought them","He had drunk them himself","The ghost must have drunk them"],"answer_index":3,"explanation_cn":"课文说 five empty whisky bottles which the ghost must have drunk,他认为是鬼魂喝的。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',9,NULL,'choice','{"stem":"你想说\"鬼魂一定把威士忌喝了\"(对过去推测用 must have + 过去分词):","options":["The ghost must have drunk the whisky.","The ghost must drank the whisky.","The ghost must have drink the whisky.","The ghost must drink the whisky."],"answer_index":0,"explanation_cn":"对过去的推测用 must have + 过去分词。✓ The ghost must have drunk the whisky. 场合:根据证据推断过去一定发生了某事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',9,NULL,'choice','{"stem":"你想说\"门被椅子堵住了\"(过去完成被动:had been + 过去分词):","options":["The doors had blocked by chairs.","The doors had been blocked by chairs.","The doors had been block by chairs.","The doors have blocked by chairs."],"answer_index":1,"explanation_cn":"过去完成被动 had been + 过去分词。✓ The doors had been blocked by chairs. 场合:说某物在更早时被(人)怎样了。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',9,NULL,'choice','{"stem":"你想说\"他打算卖掉酒馆\"(be going to 表打算):","options":["He is going sell the pub.","He is go to sell the pub.","He is going to sell the pub.","He going to sell the pub."],"answer_index":2,"explanation_cn":"表将来的打算用 be going to。✓ He is going to sell the pub. 场合:说某人打算/计划做某事。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',10,NULL,'choice','{"stem":"haunt 的意思是:","options":["(鬼)来访,闹鬼","装修","出售","打扫"],"answer_index":0,"explanation_cn":"haunt = (鬼)来访、闹鬼。✓ it is haunted 那里闹鬼。\n顺带记:打扫 = clean;装修 = decorate;出售 = sell."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',10,NULL,'choice','{"stem":"accept 的意思是:","options":["拒绝","接受","购买","归还"],"answer_index":1,"explanation_cn":"accept = 接受。✓ will not accept 不接受。\n顺带记:拒绝 = refuse;购买 = buy;归还 = return."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',10,NULL,'choice','{"stem":"\"The ghost ___ the whisky — five bottles are empty!\"(对过去推测:一定喝了)","options":["drinks","must drink","must have drunk","must drank"],"answer_index":2,"stem_cn":"鬼魂一定把威士忌喝了。","explanation_cn":"对过去的推测用 must have + 过去分词。✓ The ghost must have drunk 鬼魂一定喝了。\n✗ must drink:对现在;✗ must drank:结构错;✗ drinks:缺推测语气。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',10,NULL,'choice','{"stem":"\"The doors ___ by chairs the next morning.\"(过去完成被动)","options":["had been blocked","were blocking","had blocked","blocked"],"answer_index":0,"stem_cn":"第二天早上门被椅子堵住了。","explanation_cn":"过去完成被动:had been + 过去分词。✓ The doors had been blocked 门被堵住。\n✗ had blocked:主动;✗ blocked:一般过去主动;✗ were blocking:过去进行主动。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',10,NULL,'choice','{"stem":"\"The ghost must have drunk the whisky the night before.\" 这句话的意思是:","options":["威士忌是给鬼魂买的。","鬼魂不喝威士忌。","鬼魂想喝威士忌。","鬼魂前一晚一定把威士忌喝了。"],"answer_index":3,"explanation_cn":"The ghost must have drunk the whisky the night before. must have drunk = 对过去的推测\"一定喝了\",意思是\"鬼魂前一晚一定把威士忌喝了\"。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',10,NULL,'choice','{"stem":"\"They will not accept the pub even if he gives it away.\" 这句话的意思是:","options":["他们想买下这家酒馆。","他们接受了这家酒馆。","即使他白送,他们也不要这家酒馆。","他把酒馆送给了他们。"],"answer_index":2,"explanation_cn":"They will not accept the pub even if he gives it away. even if = \"即使\",give away = 白送,意思是\"即使他白送,他们也不要这家酒馆\"。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',10,NULL,'choice','{"stem":"What evidence made Mr. Thompson believe the pub was haunted?","options":["A ghost he saw with his own eyes","Strange noises, blocked doors, moved furniture, lights back on, and empty whisky bottles","The villagers'' warnings only","A letter from the ghost"],"answer_index":1,"passage":"A public house which was recently bought by Mr. Ian Thompson is up for sale. Mr. Thompson is going to sell it because it is haunted. He told me that he could not go to sleep one night because he heard a strange noise coming from the bar. The next morning, he found that the doors had been blocked by chairs and the furniture had been moved. Though Mr. Thompson had turned the lights off before he went to bed, they were on in the morning. He also said that he had found five empty whisky bottles which the ghost must have drunk the night before. When I suggested that some villagers must have come in for a free drink, Mr. Thompson shook his head. The villagers have told him that they will not accept the pub even if he gives it away.","explanation_cn":"课文列举了怪声、门被堵、家具被挪、灯又亮、空酒瓶等一连串\"证据\"。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',10,NULL,'choice','{"stem":"How did Mr. Thompson react when the writer suggested villagers had come in for a free drink?","options":["He called the police","He agreed at once","He shook his head, disagreeing","He laughed"],"answer_index":2,"passage":"A public house which was recently bought by Mr. Ian Thompson is up for sale. Mr. Thompson is going to sell it because it is haunted. He told me that he could not go to sleep one night because he heard a strange noise coming from the bar. The next morning, he found that the doors had been blocked by chairs and the furniture had been moved. Though Mr. Thompson had turned the lights off before he went to bed, they were on in the morning. He also said that he had found five empty whisky bottles which the ghost must have drunk the night before. When I suggested that some villagers must have come in for a free drink, Mr. Thompson shook his head. The villagers have told him that they will not accept the pub even if he gives it away.","explanation_cn":"课文说 Mr. Thompson shook his head,他摇头表示不同意\"村民进来喝酒\"的说法。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',10,NULL,'choice','{"stem":"What did Mr. Thompson hear the night he couldn''t sleep?","options":["A knock at the door","A strange noise coming from the bar","Someone singing","Nothing at all"],"answer_index":1,"audio":"A public house which was recently bought by Mr. Ian Thompson is up for sale. Mr. Thompson is going to sell it because it is haunted. He told me that he could not go to sleep one night because he heard a strange noise coming from the bar. The next morning, he found that the doors had been blocked by chairs and the furniture had been moved. Though Mr. Thompson had turned the lights off before he went to bed, they were on in the morning. He also said that he had found five empty whisky bottles which the ghost must have drunk the night before. When I suggested that some villagers must have come in for a free drink, Mr. Thompson shook his head. The villagers have told him that they will not accept the pub even if he gives it away.","explanation_cn":"课文说 he heard a strange noise coming from the bar,他听到酒吧传来怪声。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l47',10,NULL,'choice','{"stem":"Will the villagers take the pub if it is given away free?","options":["Only one of them will","Yes — they''d love it","No — they won''t accept it even for free","Only if it''s repaired"],"answer_index":2,"audio":"A public house which was recently bought by Mr. Ian Thompson is up for sale. Mr. Thompson is going to sell it because it is haunted. He told me that he could not go to sleep one night because he heard a strange noise coming from the bar. The next morning, he found that the doors had been blocked by chairs and the furniture had been moved. Though Mr. Thompson had turned the lights off before he went to bed, they were on in the morning. He also said that he had found five empty whisky bottles which the ghost must have drunk the night before. When I suggested that some villagers must have come in for a free drink, Mr. Thompson shook his head. The villagers have told him that they will not accept the pub even if he gives it away.","explanation_cn":"课文说 they will not accept the pub even if he gives it away,白送也不要。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l48',2,6,48,'Did you want to tell me something?','你想对我说什么吗?','间接引语疑问句(ask whether/if、ask how/what + 陈述语序)+ 易混词辨析(Words often confused,复习 SD26-45)主考——too vs very、steal vs rob、which vs who、continuously vs continually、past vs passed、deny vs refuse;pull out、for a while、in answer to(辅考·课文①类)','牙科医生们总是在你无法作出回答的时候向你提问。我的牙科医生刚刚给我拔掉了一颗牙,叫我休息一会儿。我想说点什么,但嘴里塞满了药棉。他知道我收集火柴盒,于是问我收藏是否在增加;接着又问我兄弟近来如何,问我是否喜欢伦敦的新工作。作为对这些问题的回答,我不是点头,就是发出奇怪的声音。与此同时,我的舌头正忙着寻找刚拔掉的那颗牙的伤口。我突然非常着急起来,但却什么也说不出来。当那位牙医最后将药棉从我嘴中取出时,我总算有可能告诉他,他拔错了牙。','{"q":"Listen and answer — Why did the writer become very worried?","options":["His tongue told him the dentist had pulled out the wrong tooth","He had a lot of pain","He had lost his job","The dentist was rude"],"answer_index":0}'::jsonb,'{"title":"间接引语疑问句 + 易混词辨析","intro":"把别人的疑问转述出来:一般疑问用 ask whether/if,特殊疑问用 ask + 疑问词(how/what),都用陈述语序(动词跟在主语后)。本课还复习一批容易混的词:too/very、steal/rob、which/who、past/passed 等。全用本课句子举例。","table":{"headers":["用法/易混词","例子"],"rows":[["ask whether / if(一般疑问)","He asked whether my collection was growing."],["ask how / what(特殊疑问)","He asked how my brother was.(陈述语序)"],["too vs very","too ill to work(太…不能)/ very ill(很)"],["steal vs rob","steal a thing(偷物)/ rob a bank(抢地方/人)"],["past vs passed","flew past my window(经过)/ three hours passed(过去了)"]]},"specialRules":[{"rule":"转述疑问句要用陈述语序:asked how my brother was(不是 how was my brother)。","mark":"疑问转述用陈述语序"},{"rule":"steal 后接被偷的东西(steal money);rob 后接被抢的地方或人(rob a bank / rob him)。","mark":"steal 物 / rob 人或地"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l48',1,NULL,'Dentists always ask questions when it is impossible for you to answer.','牙科医生们总是在你无法作出回答的时候向你提问。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l48',2,NULL,'My dentist had just pulled out one of my teeth and had told me to rest for a while.','我的牙医刚刚给我拔掉了一颗牙,叫我休息一会儿。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l48',3,NULL,'I tried to say something, but my mouth was full of cotton wool.','我想说点什么,但嘴里塞满了药棉。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l48',4,NULL,'He knew I collected match boxes and asked me whether my collection was growing.','他知道我收集火柴盒,于是问我收藏是否在增加。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l48',5,NULL,'He then asked me how my brother was and whether I liked my new job in London.','接着又问我兄弟近来如何,问我是否喜欢伦敦的新工作。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l48',6,NULL,'In answer to these questions I either nodded or made strange noises.','作为对这些问题的回答,我不是点头,就是发出奇怪的声音。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l48',7,NULL,'Meanwhile, my tongue was busy searching out the hole where the tooth had been.','与此同时,我的舌头正忙着寻找刚拔掉的那颗牙的伤口。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l48',8,NULL,'When the dentist at last removed the cotton wool from my mouth, I was able to tell him that he had pulled out the wrong tooth.','当那位牙医最后将药棉从我嘴中取出时,我总算能告诉他,他拔错了牙。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
