INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l48','cotton balls','cotton wool','药棉/棉球;美语 cotton balls,英式 cotton wool(课文 cotton wool)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l48','candy','sweets','糖果;美语 candy,英式 sweets(蛀牙/牙医主题)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l48','drugstore','chemist''s','药店;美语 drugstore,英式 chemist''s(买药棉的地方)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l48','dentist''s office','dental surgery','牙医诊所;美语 dentist''s office,英式 dental surgery') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l48','ask whether / how','',NULL,'/æsk ˈweðər/','He asked whether my collection was growing.','他问我收藏是否在增加。','He asked how my brother was.','他问我兄弟近来如何。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l48','pull out (a tooth)','',NULL,'/pʊl aʊt/','The dentist had pulled out one of my teeth.','牙医拔掉了我一颗牙。','He pulled out the wrong tooth.','他拔错了牙。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l48','for a while','',NULL,'/fɔːr ə waɪl/','He told me to rest for a while.','他叫我休息一会儿。','Let''s wait for a while.','我们等一会儿吧。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l48','in answer to','',NULL,'/ɪn ˈænsər tuː/','In answer to these questions, I nodded.','作为对这些问题的回答,我点点头。','She smiled in answer to my question.','她笑着回答我的问题。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',5,'am2_l48_gp1','choice','{"stem":"\"He asked me ___ my collection was growing.\"(间接引语一般疑问:是否)","options":["what","whether","how","that"],"answer_index":1,"stem_cn":"他问我收藏是否在增加。","explanation_cn":"转述一般疑问用 ask whether(是否)。✓ asked whether my collection was growing 问收藏是否在增加。✗ that:用于陈述句转述;✗ what / how:是特殊疑问词,这里没问\"什么/怎样\"。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',5,'am2_l48_gp1','choice','{"stem":"\"He asked ___ I liked my new job in London.\"(间接引语一般疑问:是否)","options":["that","when","whether","what"],"answer_index":2,"stem_cn":"他问我是否喜欢伦敦的新工作。","explanation_cn":"转述一般疑问用 ask whether(是否)。✓ asked whether I liked my job 问是否喜欢工作。✗ that:陈述句转述;✗ what / when:没问\"什么/何时\"。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',5,'am2_l48_gp1','choice','{"stem":"\"She asked ___ I had ever been to a dentist.\"(间接引语一般疑问:是否)","options":["that","what","how","if"],"answer_index":3,"stem_cn":"她问我是否看过牙医。","explanation_cn":"转述一般疑问也可用 ask if(同 whether)。✓ asked if I had been to a dentist 问是否看过牙医。✗ that:陈述句转述;✗ what / how:没问\"什么/怎样\"。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',5,'am2_l48_gp1','choice','{"stem":"\"I wondered ___ the dentist had pulled the right tooth.\"(间接引语一般疑问:是否)","options":["whether","what","that","which"],"answer_index":0,"stem_cn":"我在想牙医是否拔对了牙。","explanation_cn":"\"想…是否\",一般疑问内容用 whether。✓ wondered whether the dentist had pulled the right tooth。✗ that:陈述句转述;✗ what:没问\"什么\";✗ which:没问\"哪一个\"。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',5,'am2_l48_gp2','choice','{"stem":"\"He asked me ___ my brother was.\"(间接引语特殊疑问:怎么样)","options":["whether","if","that","how"],"answer_index":3,"stem_cn":"他问我兄弟近来如何。","explanation_cn":"转述特殊疑问\"怎么样\"用 ask how。✓ asked how my brother was 问兄弟近来如何。✗ whether / if:那是转述一般疑问;✗ that:陈述句转述。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',5,'am2_l48_gp2','choice','{"stem":"\"He asked me how my brother ___.\"(转述后动词跟在主语后,不倒装)","options":["was","was he","is","did he"],"answer_index":0,"stem_cn":"他问我兄弟近来如何。","explanation_cn":"转述疑问句用陈述语序,动词跟在主语后。✓ how my brother was(不是 how was my brother)。✗ was he:那是倒装疑问语序;✗ is:时态不符;✗ did he:倒装且多余。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',5,'am2_l48_gp3','choice','{"stem":"\"He is ___ ill to do any work.\"(太…以致不能做某事)","options":["very","so","much","too"],"answer_index":3,"stem_cn":"他病得太重,干不了活。","explanation_cn":"\"太…以致不能做某事\"用 too + 形容词 + to do。✓ too ill to work 病得太重干不了活。✗ very:只表\"很\",不含\"不能\"的意思;✗ so:需配 that;✗ much:不与 ill 这样搭。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',5,'am2_l48_gp3','choice','{"stem":"\"The soup is ___ hot, and I like it that way.\"(仅表''很'',中性)","options":["too","very","so that","much"],"answer_index":1,"stem_cn":"这汤很烫,我就喜欢这样。","explanation_cn":"只表\"很\"(中性)用 very。✓ very hot, and I like it 很烫,我喜欢。✗ too:表\"太…(不好)\",与\"喜欢\"矛盾;✗ so that:结构不对;✗ much:不修饰 hot。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',5,'am2_l48_gp4','choice','{"stem":"\"The bank ___ last night.\"(抢劫银行/某人)","options":["robbed","stole","was robbed","was stolen"],"answer_index":2,"stem_cn":"银行昨晚被抢劫了。","explanation_cn":"rob 后接被抢的地方或人(rob a bank / a person),被动 was robbed。✓ The bank was robbed 银行被抢。✗ was stolen:steal 接被偷的东西,不接地方;✗ robbed / stole:主动,与\"银行被…\"不符。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',5,'am2_l48_gp4','choice','{"stem":"\"My wallet ___ on the bus.\"(偷走某物)","options":["was stolen","robbed","was robbed","stole"],"answer_index":0,"stem_cn":"我的钱包在公交车上被偷了。","explanation_cn":"steal 后接被偷的东西(steal a wallet),被动 was stolen。✓ My wallet was stolen 钱包被偷。✗ was robbed:rob 接人/地方,不接物;✗ stole / robbed:主动,与\"钱包被…\"不符。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',5,'am2_l48_gp5','choice','{"stem":"\"The new school, ___ has just been completed, is fine.\"(先行词指物时)","options":["whom","which","what","who"],"answer_index":1,"stem_cn":"刚建成的新学校很不错。","explanation_cn":"先行词指物时,关系词用 which。✓ the school, which has just been completed 刚建成的学校。✗ who / whom:指人;✗ what:不引导定语从句。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',5,'am2_l48_gp5','choice','{"stem":"\"The dentist ___ pulled my tooth was very kind.\"(先行词指人时)","options":["what","which","whom","who"],"answer_index":3,"stem_cn":"给我拔牙的牙医很和善。","explanation_cn":"先行词指人时,关系词用 who。✓ the dentist who pulled my tooth 给我拔牙的牙医。✗ which:指物;✗ whom:此处作从句主语用 who;✗ what:不引导定语从句。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',5,'am2_l48_gp6','choice','{"stem":"\"The ship sailed ___ across the sea for three days.\"(连续不间断地)","options":["continually","continuously","carefully","suddenly"],"answer_index":1,"stem_cn":"船连续不断地航行了三天。","explanation_cn":"continuously 表\"连续不间断地\"。✓ sailed continuously for three days 连续航行三天。✗ continually:表\"反复、时断时续\";✗ suddenly:突然;✗ carefully:仔细地。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',5,'am2_l48_gp6','choice','{"stem":"\"He ___ interrupts me when I speak.\"(反复地、时断时续地)","options":["continually","slowly","quietly","continuously"],"answer_index":0,"stem_cn":"我说话时他不断打断我。","explanation_cn":"continually 表\"反复地、一次又一次(有间断)\"。✓ continually interrupts me 不断打断我。✗ continuously:表\"不间断\";✗ quietly / slowly:意思不符。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',5,'am2_l48_gp7','choice','{"stem":"\"A bird flew ___ my window.\"(从…旁边经过,表方位)","options":["pass","past","passing","passed"],"answer_index":1,"stem_cn":"一只鸟从我窗前飞过。","explanation_cn":"\"从…旁边经过\"用介词/副词 past。✓ flew past my window 从窗前飞过。✗ passed:那是动词过去式;✗ passing / pass:结构不对。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',5,'am2_l48_gp7','choice','{"stem":"\"Three hours ___ before he came back.\"(时间''过去了'',用动词)","options":["passing","pass","past","passed"],"answer_index":3,"stem_cn":"过了三个小时他才回来。","explanation_cn":"\"(时间)过去了\"用动词 pass 的过去式 passed。✓ Three hours passed 过了三个小时。✗ past:是介词/副词,不作谓语;✗ passing / pass:时态不符。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',5,'am2_l48_gp8','choice','{"stem":"\"He ___ that he had taken it.\"(否认做过某事)","options":["refused","denied","rejected","accepted"],"answer_index":1,"stem_cn":"他否认拿过它。","explanation_cn":"\"否认做过某事\"用 deny(后接 that 从句或动名词)。✓ denied that he had taken it 否认拿过。✗ refused:是\"拒绝(做)\";✗ rejected:是\"拒收/否决\";✗ accepted:是\"接受\"。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',5,'am2_l48_gp8','choice','{"stem":"\"He ___ to answer the question.\"(拒绝做某事)","options":["refused","denied","rejected","accepted"],"answer_index":0,"stem_cn":"他拒绝回答问题。","explanation_cn":"\"拒绝做某事\"用 refuse to do。✓ refused to answer 拒绝回答。✗ denied:是\"否认\";✗ rejected:是\"否决/拒收\";✗ accepted:是\"接受\"。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',6,NULL,'choice','{"stem":"美语里\"药棉/棉球\"常说:","options":["cotton balls","cotton wool","medical cotton","wool balls"],"answer_index":0,"explanation_cn":"美语\"药棉/棉球\"常说 cotton balls;英式说 cotton wool。✓ a few cotton balls 几个棉球。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',6,NULL,'choice','{"stem":"美语里\"糖果\"常说:","options":["sweets","candy","lollies","sugars"],"answer_index":1,"explanation_cn":"美语\"糖果\"常说 candy;英式说 sweets。✓ a piece of candy 一块糖。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',6,NULL,'choice','{"stem":"collect 的意思是:","options":["收集,搜集","出售","破坏","丢弃"],"answer_index":0,"explanation_cn":"collect = 收集、搜集。✓ I collected match boxes 我收集火柴盒。\n顺带记:丢弃 = throw away;出售 = sell;破坏 = destroy."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',6,NULL,'choice','{"stem":"nod 的意思是:","options":["摇头","眨眼","点头","招手"],"answer_index":2,"explanation_cn":"nod = 点头。✓ I either nodded or made noises 我不是点头就是出声。\n顺带记:摇头 = shake one''s head;眨眼 = blink;招手 = wave."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',6,NULL,'choice','{"stem":"meanwhile 的意思是:","options":["之后","从不","很久以前","同时,与此同时"],"answer_index":3,"explanation_cn":"meanwhile = 同时、与此同时。✓ Meanwhile, my tongue was busy 与此同时舌头忙着。\n顺带记:之后 = afterwards;很久以前 = long ago;从不 = never."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',6,NULL,'choice','{"stem":"pull 的意思是:","options":["拔,拉","扔","举","推"],"answer_index":0,"explanation_cn":"pull = 拔、拉。✓ pulled out a tooth 拔掉一颗牙。\n顺带记:推 = push;举 = lift;扔 = throw."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',7,NULL,'cloze','{"stem":"第 1 空","context":"The dentist asked me ___1___ my collection was growing, and ___2___ my brother was. My mouth was full of cotton wool, so I only nodded. When he removed it, I was able to tell him he had pulled out the ___3___ tooth — I felt ___4___ worried.","blank_no":1,"options":["whether","that","what","how"],"answer_index":0,"explanation_cn":"转述一般疑问用 ask whether(是否)。✓ asked whether my collection was growing 问收藏是否在增加。\n✗ that:陈述句转述;✗ what / how:没问\"什么/怎样\"。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',7,NULL,'cloze','{"stem":"第 2 空","context":"The dentist asked me ___1___ my collection was growing, and ___2___ my brother was. My mouth was full of cotton wool, so I only nodded. When he removed it, I was able to tell him he had pulled out the ___3___ tooth — I felt ___4___ worried.","blank_no":2,"options":["how","whether","that","if"],"answer_index":0,"explanation_cn":"转述特殊疑问\"怎么样\"用 ask how。✓ asked how my brother was 问兄弟近来如何。\n✗ whether / if:转述一般疑问;✗ that:陈述句转述。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',7,NULL,'cloze','{"stem":"第 3 空","context":"The dentist asked me ___1___ my collection was growing, and ___2___ my brother was. My mouth was full of cotton wool, so I only nodded. When he removed it, I was able to tell him he had pulled out the ___3___ tooth — I felt ___4___ worried.","blank_no":3,"options":["wrong","wrongly","false","bad"],"answer_index":0,"explanation_cn":"\"拔错了牙\"用形容词 wrong 修饰 tooth。✓ the wrong tooth 拔错的那颗牙。\n✗ wrongly:是副词,不作定语;✗ false:意为\"假的\";✗ bad:意为\"坏的\",不表\"错的那颗\"。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',7,NULL,'cloze','{"stem":"第 4 空","context":"The dentist asked me ___1___ my collection was growing, and ___2___ my brother was. My mouth was full of cotton wool, so I only nodded. When he removed it, I was able to tell him he had pulled out the ___3___ tooth — I felt ___4___ worried.","blank_no":4,"options":["very","too","so that","much"],"answer_index":0,"explanation_cn":"只表\"很\"(中性)用 very。✓ very worried 很着急。\n✗ too:表\"太…(不好)\",此处不含\"不能\";✗ so that:结构不对;✗ much:不修饰 worried。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',8,NULL,'choice','{"stem":"What had the dentist just done at the start of the story?","options":["Pulled out one of the writer''s teeth","Cleaned his teeth","Taken an X-ray","Given him medicine"],"answer_index":0,"explanation_cn":"课文说 My dentist had just pulled out one of my teeth,牙医刚拔掉他一颗牙。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',8,NULL,'choice','{"stem":"Why couldn''t the writer answer the dentist''s questions?","options":["He didn''t speak English","He didn''t hear them","His mouth was full of cotton wool","He was asleep"],"answer_index":2,"explanation_cn":"课文说 my mouth was full of cotton wool,嘴里塞满药棉说不出话。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',8,NULL,'choice','{"stem":"What did the writer realize while his tongue searched the hole?","options":["The tooth was fine","The dentist had pulled out the wrong tooth","He had swallowed the tooth","He needed another filling"],"answer_index":1,"explanation_cn":"课文结尾说 he had pulled out the wrong tooth,牙医拔错了牙。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',9,NULL,'choice','{"stem":"你想转述\"你的收藏在增加吗?\"(一般疑问用 ask whether/if):","options":["He asked is my collection growing.","He asked whether my collection was growing.","He asked that my collection was growing.","He asked whether was my collection growing."],"answer_index":1,"explanation_cn":"转述一般疑问用 ask whether,后接陈述语序。✓ He asked whether my collection was growing. 场合:把别人问的一般疑问转述出来。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',9,NULL,'choice','{"stem":"你想转述\"你兄弟近来如何?\"(特殊疑问用 ask how + 陈述语序):","options":["He asked how my brother was.","He asked that how my brother was.","He asked how my brother is.","He asked how was my brother."],"answer_index":0,"explanation_cn":"转述特殊疑问用 ask + 疑问词,不再倒装、用陈述语序。✓ He asked how my brother was(不是 how was my brother)。场合:把\"你兄弟怎么样\"转述出来。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',9,NULL,'choice','{"stem":"你想说\"他病得太重,干不了活\"(too...to 太…而不能):","options":["He is too ill to doing any work.","He is so ill to do any work.","He is very ill to do any work.","He is too ill to do any work."],"answer_index":3,"explanation_cn":"\"太…以致不能做某事\"用 too + 形容词 + to do。✓ He is too ill to do any work. 场合:说某人太怎样以致做不了某事。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',10,NULL,'choice','{"stem":"collect 的意思是:","options":["丢弃","收集,搜集","破坏","出售"],"answer_index":1,"explanation_cn":"collect = 收集、搜集。✓ collect match boxes 收集火柴盒。\n顺带记:丢弃 = throw away;破坏 = destroy;出售 = sell."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',10,NULL,'choice','{"stem":"nod 的意思是:","options":["摇头","眨眼","跺脚","点头"],"answer_index":3,"explanation_cn":"nod = 点头。✓ I nodded 我点了点头。\n顺带记:摇头 = shake one''s head;眨眼 = blink;跺脚 = stamp."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',10,NULL,'choice','{"stem":"\"He asked ___ my collection was growing.\"(间接引语一般疑问:是否)","options":["whether","that","how","what"],"answer_index":0,"stem_cn":"他问我收藏是否在增加。","explanation_cn":"转述一般疑问用 ask whether(是否)。✓ asked whether my collection was growing 问收藏是否在增加。\n✗ that:陈述句转述;✗ what / how:没问\"什么/怎样\"。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',10,NULL,'choice','{"stem":"\"He asked me ___ my brother was.\"(间接引语特殊疑问:怎么样)","options":["if","that","how","whether"],"answer_index":2,"stem_cn":"他问我兄弟近来如何。","explanation_cn":"转述特殊疑问\"怎么样\"用 ask how。✓ asked how my brother was 问兄弟近来如何。\n✗ whether / if:转述一般疑问;✗ that:陈述句转述。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',10,NULL,'choice','{"stem":"\"He had pulled out the wrong tooth.\" 这句话的意思是:","options":["他拔了两颗牙。","他没拔牙。","他拔掉了一颗坏牙。","他拔错了牙。"],"answer_index":3,"explanation_cn":"He had pulled out the wrong tooth. the wrong tooth = 错的那颗牙,意思是\"他拔错了牙\"。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',10,NULL,'choice','{"stem":"\"Dentists always ask questions when it is impossible for you to answer.\" 这句话的意思是:","options":["病人总在提问。","牙医总是在你无法回答的时候提问。","牙医从不提问。","牙医只在你能回答时提问。"],"answer_index":1,"explanation_cn":"Dentists always ask questions when it is impossible for you to answer. 意思是\"牙医总是在你无法回答的时候提问\"——因为嘴里在治疗。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',10,NULL,'choice','{"stem":"Why did the writer only nod or make strange noises?","options":["His mouth was full of cotton wool so he couldn''t speak","He didn''t understand the questions","He was too shy","He was angry at the dentist"],"answer_index":0,"passage":"Dentists always ask questions when it is impossible for you to answer. My dentist had just pulled out one of my teeth and had told me to rest for a while. I tried to say something, but my mouth was full of cotton wool. He knew I collected match boxes and asked me whether my collection was growing. He then asked me how my brother was and whether I liked my new job in London. In answer to these questions I either nodded or made strange noises. Meanwhile, my tongue was busy searching out the hole where the tooth had been. I suddenly felt very worried, but could not say anything. When the dentist at last removed the cotton wool from my mouth, I was able to tell him that he had pulled out the wrong tooth.","explanation_cn":"课文说他嘴里塞满药棉,只能点头或发出怪声作答。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',10,NULL,'choice','{"stem":"Why did the writer suddenly feel very worried?","options":["The dentist looked angry","He had lost his match box collection","The pain was terrible","His tongue found that the wrong tooth had been pulled out"],"answer_index":3,"passage":"Dentists always ask questions when it is impossible for you to answer. My dentist had just pulled out one of my teeth and had told me to rest for a while. I tried to say something, but my mouth was full of cotton wool. He knew I collected match boxes and asked me whether my collection was growing. He then asked me how my brother was and whether I liked my new job in London. In answer to these questions I either nodded or made strange noises. Meanwhile, my tongue was busy searching out the hole where the tooth had been. I suddenly felt very worried, but could not say anything. When the dentist at last removed the cotton wool from my mouth, I was able to tell him that he had pulled out the wrong tooth.","explanation_cn":"课文说他舌头找伤口时发现拔错了牙,所以突然非常着急。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',10,NULL,'choice','{"stem":"What does the writer collect?","options":["Toy cars","Match boxes","Stamps","Old coins"],"answer_index":1,"audio":"Dentists always ask questions when it is impossible for you to answer. My dentist had just pulled out one of my teeth and had told me to rest for a while. I tried to say something, but my mouth was full of cotton wool. He knew I collected match boxes and asked me whether my collection was growing. He then asked me how my brother was and whether I liked my new job in London. In answer to these questions I either nodded or made strange noises. Meanwhile, my tongue was busy searching out the hole where the tooth had been. I suddenly felt very worried, but could not say anything. When the dentist at last removed the cotton wool from my mouth, I was able to tell him that he had pulled out the wrong tooth.","explanation_cn":"课文说 He knew I collected match boxes,他收集火柴盒。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l48',10,NULL,'choice','{"stem":"When was the writer finally able to speak?","options":["When the dentist removed the cotton wool from his mouth","He never spoke","As soon as he sat down","Before the tooth was pulled"],"answer_index":0,"audio":"Dentists always ask questions when it is impossible for you to answer. My dentist had just pulled out one of my teeth and had told me to rest for a while. I tried to say something, but my mouth was full of cotton wool. He knew I collected match boxes and asked me whether my collection was growing. He then asked me how my brother was and whether I liked my new job in London. In answer to these questions I either nodded or made strange noises. Meanwhile, my tongue was busy searching out the hole where the tooth had been. I suddenly felt very worried, but could not say anything. When the dentist at last removed the cotton wool from my mouth, I was able to tell him that he had pulled out the wrong tooth.","explanation_cn":"课文说牙医取出药棉后,他才总算能说话告诉牙医拔错了。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
